window.WORDS_RAW=[[1,310,"personal","/ˈpɜːsənl/",[["adj","私人的，个人的"]],[],"","adj.","个人的；私人的","Every great journey begins as a personal question.","每一段伟大的旅程，都始于一个私人的疑问。",""],[2,289,"tie","/taɪ/",[["v","系，联系"],["n","关系；领带；纽带；平局"]],[],"","n.","纽带；联系","The ties that hold us are often invisible.","将我们相连的纽带，往往看不见。",""],[3,237,"still","/stɪl/",[["adj","静止的"],["adv","甚至，仍然"]],[],"","adv.","仍然；还","Faith is the bird that feels the light and sings when the dawn is still dark.","信念是一只鸟，黎明仍黑时，它已感到光明而歌唱。","泰戈尔"],[4,228,"offer","/ˈɔːfə/",[["v","提供，出（价）；愿意（做某事）"],["n","主动提议；建议；出价，报价；（通常为短期的）减价，削价；处理价；特价"]],[],"","v.","提供；愿意做","Every morning offers a clean page.","每个清晨，都递来一页干净的纸。",""],[5,202,"addition","/əˈdiʃən/",[["n","增加；附加物"]],[],"","n.","增加；附加物","A small addition each day becomes a library.","每天添一点，终会成为一座图书馆。",""],[6,188,"success","/səkˈses/",[["n","【U】成功；【C】成功的人（或事物）"]],[],"","n.","成功","Success is counted sweetest by those who ne'er succeed.","从未成功的人，才把成功看得最甜。","艾米莉·狄金森"],[7,187,"produce","/prəˈdjuːs/",[["v","生产，引起"],["n","（农）产品"]],[],"","v.","生产；引起","Pressure can produce diamonds, but so can patience.","压力能造出钻石，耐心也能。",""],[8,185,"expect","/iksˈpekt/",[["v","预料，预计；期待"]],[],"","v.","预料；期待","Expect nothing, notice everything.","不去预设，留心万物。",""],[9,178,"cause","/kɔːz/",[["v","引起"],["n","原因；事业；目标"]],[],"","n.","原因；事业","Find a cause worth getting up early for.","找一件值得早起的事业。",""],[10,177,"state","/steɪt/",[["n","情形，状态"],["v","声明，陈述"],["adj","国家的"]],[],"","n.","状态；国家","Calm is not a place, but a state of mind.","平静不是一个地方，而是一种心境。",""],[11,169,"manage","/ˈmænidʒ/",[["v","管理；设法做成（to）"]],[],"","v.","管理；设法做成","We managed to laugh, even in the rain.","就算在雨里，我们也设法笑了出来。",""],[12,166,"directly","/diˈrektli/",[["adv","直接地"],["conj","一......就"]],[],"","adv.","直接地；径直","Moonlight falls directly into the open window.","月光径直落进敞开的窗。",""],[13,165,"improve","/imˈpruːv/",[["v","改善，提高"]],[],"","v.","改善；提高","To improve is to change; to be perfect is to change often.","改进就是改变；要做到完美，就要常常改变。","丘吉尔"],[14,162,"wonder","/ˈwʌndə/",[["n","奇迹"],["v","（对某事）感到疑惑；想要知道；怀疑"]],[],"","v.","想知道；好奇","I wonder if the stars wonder about us.","我在想，星星会不会也在想我们。",""],[15,160,"present","/ˈpreznt/",[["adj","当前的，出席的"],["v","呈现；赠送；出席"],["n","礼物；现在"]],[],"","n.","礼物；现在","The present is the only time we truly hold.","此刻，是我们唯一真正握在手里的时光。",""],[16,160,"underline","/ˌʌndəˈlain/",[["v","在…下面划线；强调"]],[],"","v.","在…下画线；强调","Underline the lines that made you think.","把让你停下来思考的句子画上线。",""],[17,159,"mislead","/misˈliːd/",[["v","误导；将…引入歧途"]],[],"","v.","误导","First impressions can mislead; give people time.","第一印象会误导人，给彼此一点时间。",""],[18,157,"complete","/kəmˈpliːt/",[["v","完成"],["adj","完整的"]],[],"","adj.","完整的；彻底的","A complete sentence, like a complete day, needs a full stop.","完整的句子和完整的一天一样，都需要一个句号。",""],[19,154,"lead","/liːd/",[["v","导致（to），带领；过（…的生活）"],["n","领头位置；铅（一种化学元素）"]],[],"","v.","带领；导致","Let the stars lead you home.","让星星带你回家。",""],[20,153,"sensitive","/ˈsensitiv/",[["adj","敏感的；（对光﹑温度﹑位置等的细微变化）敏感度高的，灵敏的；体贴的，体恤的，善解人意的"]],[],"","adj.","敏感的；灵敏的","A sensitive ear can hear the snow falling.","灵敏的耳朵，能听见雪落下的声音。",""],[21,147,"valuable","/ˈvæljuəbl/",[["adj","贵重的；珍贵的，宝贵的"]],[],"","adj.","珍贵的；宝贵的","Time is the most valuable thing a person can spend.","时间是一个人能花出去的最贵重的东西。",""],[22,146,"courageous","/kəˈreɪdʒəs/",[["adj","勇敢的"]],[],"","adj.","勇敢的","Being courageous means being afraid and going anyway.","勇敢，就是害怕了也照样往前走。",""],[23,144,"tend","/tend/",[["v","趋向，照顾（to）"]],[],"","v.","往往会；照料","Gardeners tend their roses; we must tend our dreams.","园丁照料玫瑰，我们得照料自己的梦想。",""],[24,141,"matter","/ˈmætə/",[["n","事情"],["v","要紧"]],[],"","v.","要紧；n. 事情","What matters most is how you walk through the fire.","最要紧的，是你怎样穿过火焰。",""],[25,136,"realise","/ˈriəlaiz/",[["v","意识到，认识到；实现（梦想）"]],[],"","v.","意识到；实现","One day you'll realise how far you've come.","总有一天，你会意识到自己已经走了多远。",""],[26,131,"acceptable","/əkˈseptəbl/",[["adj","可接受的；合意的"]],[],"","adj.","可接受的","Mistakes are acceptable; giving up is not.","犯错可以接受，放弃不行。",""],[27,131,"consider","/kənˈsidə/",[["v","考虑，认为"]],[],"","v.","考虑；认为","Consider the lilies: they don't hurry, yet they bloom.","看看百合吧，它们从不着急，却依然盛开。",""],[28,126,"support","/səˈpɔːt/",[["v","支持；扶持；养活；赡养；支撑"],["n","支持；支撑【U】；支撑物；支承；支柱；支座【C】"]],[],"","v.","支持；支撑","Old trees support each other underground.","老树在地下，彼此支撑。",""],[29,125,"fit","/fit/",[["adj","适宜的；健康的"],["v","安装（in），适合，使胜任（某工作）；将…放（进）；小心固定；稳固放置"],["n","一阵（忍不住的咳嗽、笑）"]],[],"","v.","适合；合身","Not every key fits every door, and that's fine.","不是每把钥匙都配得上每扇门，这没关系。",""],[30,124,"hang","/hæŋ/",[["v","挂；悬挂；（使）低垂，下垂；（被）绞死，施以绞刑"]],[],"","v.","悬挂；挂","A paper moon hangs above my desk.","一个纸月亮，挂在我的书桌上方。",""],[31,123,"protect","/prəˈtekt/",[["v","保护；防护"]],[],"","v.","保护；防护","Fallen petals are not heartless; they turn to soil to protect the flowers.","落红不是无情物，化作春泥更护花。","龚自珍"],[32,113,"professional","/prəˈfeʃənəl/",[["adj","专业的；内行的；高水平的"],["n","职业，专业；专业人士；专家；职业运动员；内行；技术精湛者"]],[],"","adj.","专业的；职业的","Every professional was once a beginner.","每个专业的人，都曾是新手。",""],[33,112,"widen","/ˈwaidn/",[["v","使变宽；（使）（范围）扩大"]],[],"","v.","使变宽；扩大","To widen your view a thousand miles, climb one more floor.","欲穷千里目，更上一层楼。","王之涣"],[34,105,"require","/riˈkwaiə/",[["v","要求；要（某物）"]],[],"","v.","需要；要求","Great things require a long, quiet patience.","伟大的事，需要漫长而安静的耐心。",""],[35,104,"creative","/kriˈeɪtɪv/",[["adj","创造性的；有创造力的"]],[],"","adj.","有创造力的","Boredom is often where creative ideas are born.","无聊的时刻，常常是创意诞生的地方。",""],[36,104,"deal","/diːl/",[["v","处理（with）"],["n","交易；待遇"]],[],"","v.","处理；应对","Deal with today; tomorrow has its own light.","先应付好今天，明天自有明天的光。",""],[37,100,"popularity","/ˌpɔpjuˈlæriti/",[["n","普及，流行"]],[],"","n.","受欢迎；流行","Popularity fades; kindness is remembered.","人气会褪去，善良会被记住。",""],[38,99,"attend","/əˈtend/",[["v","出席，关心（to）；处理（to）；去（学校、教堂等）；上（学）"]],[],"","v.","出席；照料","Attend to the small things, and the big ones follow.","照顾好小事，大事自然会跟上。",""],[39,98,"prefer","/priˈfəː/",[["v","更喜欢"]],[],"","v.","更喜欢","I prefer the quiet of early morning to any party.","比起任何派对，我更喜欢清晨的安静。",""],[40,97,"wild","/waild/",[["adj","野生的"],["n","自然环境；野生状态"],["n","[pl]偏远地区；人烟稀少的地区"]],[],"","adj.","野生的；狂热的","To see a world in a grain of sand, and a heaven in a wild flower.","一沙一世界，一花一天堂。","威廉·布莱克"],[41,93,"quality","/ˈkwɔliti/",[["n","质量，品质"]],[],"","n.","质量；品质","The quality of mercy is not strained.","仁慈的品质，从不出于勉强。","莎士比亚"],[42,91,"perform","/pəˈfɔːm/",[["v","执行，履行，做；做表演；工作；运转"]],[],"","v.","表演；执行","The orchestra performs best when everyone listens.","每个人都在倾听时，乐团演奏得最好。",""],[43,90,"promise","/ˈprɔmis/",[["n","获得成功的迹象；吉兆，迹象；诺言"],["v","允诺，答应"]],[],"","n.","诺言；希望","Every sunrise carries a promise.","每一次日出，都带着一个诺言。",""],[44,90,"necessarily","/ˈnesəserili/",[["adv","必然地，不可避免地；必要地"]],[],"","adv.","必然地","Slow does not necessarily mean wrong.","慢，不一定就是错。",""],[45,90,"store","/stɔː(r)/",[["v","储存"],["n","商店"]],[],"","v.","储存；n. 商店","Squirrels store nuts; I store good memories.","松鼠储存坚果，我储存美好的回忆。",""],[46,88,"general","/ˈdʒenərəl/",[["adj","普遍的；一般的，常规的；概括性的，大体的，笼统的；首席的，总管的【只用在名词前】"]],[],"","adj.","普遍的；总体的","In general, things look better after a good sleep.","总的来说，睡个好觉之后，一切都会好看些。",""],[47,87,"condition","/kənˈdɪʃn/",[["n","情况，条件；（因不可能治愈而长期患有的）疾病；（先决）；条件；前提；（某群体的）生存状态，处境"],["v","使习惯于；使适应"]],[],"","n.","条件；状况","Seeds wait for the right conditions to wake.","种子在等待合适的条件醒来。",""],[48,87,"vary","/ˈvɛəri/",[["v","改变；不同，有差异"]],[],"","v.","变化；不同","Our joys and sorrows vary, as the moon waxes and wanes.","人有悲欢离合，月有阴晴圆缺。","苏轼"],[49,85,"suffer","/ˈsʌfə(r)/",[["v","（因疾病、痛苦、悲伤等）受苦，受难，受折磨；遭受；蒙受；变差；变糟"]],[],"","v.","受苦；遭受","We suffer more in imagination than in reality.","我们在想象中受的苦，比现实中多。","塞涅卡"],[50,84,"speech","/spiːtʃ/",[["n","演讲，发言；说话的能力；口语"]],[],"","n.","演讲；说话能力","The best speech is often the shortest one.","最好的演讲，往往是最短的那一篇。",""],[51,83,"respect","/riˈspekt/",[["v","尊敬，尊重"],["n","尊敬，尊重；（事物的）方面，细节"]],[],"","v.","尊重；n. 尊敬","Respect the rhythm of your own growth.","尊重你自己成长的节奏。",""],[52,82,"disappoint","/disəˈpɔint/",[["v","使失望"]],[],"","v.","使失望","Hard work rarely disappoints those who keep at it.","努力很少辜负一直坚持的人。",""],[53,82,"simplify","/ˈsimplifai/",[["v","简化，使简单"]],[],"","v.","简化","Our life is frittered away by detail. Simplify, simplify.","生活被琐碎消耗殆尽。简化，再简化。","梭罗"],[54,81,"raise","/reiz/",[["v","举起；筹集；提出；抚养，养育；饲养，种植"]],[],"","v.","举起；提出；养育","Raise your words, not your voice.","提升你的言辞，而不是你的音量。",""],[55,80,"refer","/riˈfəː/",[["v","涉及，提到；查阅（to）"]],[],"","v.","提到；参考","Refer to the map, but trust your feet too.","参考地图，也要相信你的双脚。",""],[56,79,"achievement","/əˈtʃiːvmənt/",[["n","成就"]],[],"","n.","成就","Every achievement starts with deciding to try.","每一项成就，都始于决定去试试。",""],[57,79,"particular","/pəˈtikjulə/",[["adj","特定的，特指的；讲究的，挑剔的"]],[],"","adj.","特定的；挑剔的","Cats are very particular about their sunny spots.","猫对晒太阳的位置，可挑剔了。",""],[58,78,"prevent","/priˈvent/",[["v","阻止"]],[],"","v.","阻止；预防","Nothing can prevent the spring from coming.","什么也阻止不了春天到来。",""],[59,78,"regular","/ˈregjulə/",[["adj","有规律的，定期的"],["n","常客"]],[],"","adj.","有规律的；定期的","Regular practice beats occasional genius.","有规律的练习，胜过偶尔的灵光。",""],[60,78,"connect","/kəˈnekt/",[["v","连接，联系（with）"]],[],"","v.","连接；联系","Books connect us to people we will never meet.","书把我们和永远不会见面的人连在一起。",""],[61,78,"subject","/ˈsʌbdʒɪkt/",[["n","主题，实验对象"],["adj","服从的；取决于；视…而定；可能受…影响的；易遭受…的"]],[],"","n.","主题；科目","Every subject is interesting with the right teacher.","遇到对的老师，每一门科目都有趣。",""],[62,75,"physical","/ˈfizikəl/",[["adj","物质的，身体的"]],[],"","adj.","身体的；物质的","Physical exercise clears a crowded mind.","身体的锻炼，能清空拥挤的头脑。",""],[63,75,"check","/tʃek/",[["n","支票，检查；账单"],["v","核对"]],[],"","v.","检查；核对","Check your answers once, then trust them.","检查一遍答案，然后相信它。",""],[64,75,"position","/pəˈziʃən/",[["n","位置，立场"],["v","定位，安置"]],[],"","n.","位置；立场","Change your position, and the view changes too.","换个位置，风景也就变了。",""],[65,74,"concern","/kənˈsɜːn/",[["v","涉及；让......担忧"],["n","担心，忧虑；关爱，关心；生意兴隆的业务；发展中的事业"]],[],"","v.","涉及；使担忧","Don't let tomorrow's rain concern today's sunshine.","别让明天的雨，打扰今天的阳光。",""],[66,74,"force","/fɔːs/",[["v","强迫"],["n","力；力量；武力"]],[],"","n.","力量；v. 强迫","Water is soft, yet its force shapes mountains.","水是柔软的，它的力量却能塑造山川。",""],[67,74,"satisfy","/ˈsætisfai/",[["v","使满意；使满足"]],[],"","v.","使满意；满足","A simple meal can satisfy a tired heart.","一顿简单的饭菜，就能满足疲惫的心。",""],[68,71,"organize","/ˈɔːgənaiz/",[["v","组织；整理，使有条理"]],["organise"],"英式拼写 organise","v.","组织；整理","Organize your desk, and your thoughts will follow.","整理好书桌，思绪也会跟着变清晰。",""],[69,70,"charge","/tʃɑːdʒ/",[["n","要价，收费；控告；指责；职责，责任；充电；突然猛冲"],["v","收费，要价；控告，起诉；把…记在账上；在某人账上记入；突然猛冲；向…方向冲去；充电"]],[],"","n.","负责；费用；电量","Take charge of your own little corner of the world.","把你自己的那一小片世界负起责来。",""],[70,70,"favour","/ˈfeivə/",[["n","帮助，好事，恩惠；赞同；支持"],["v","较喜欢；特别照顾；偏袒；有助于；有利于"]],["favor"],"美式拼写 favor","n.","帮助；恩惠","Do yourself a favour: go to bed early tonight.","帮自己一个忙：今晚早点睡。",""],[71,70,"damage","/ˈdæmidʒ/",[["v","损害"],["n","损害；损伤"]],[],"","v.","损害；损伤","Harsh words damage more than broken glass.","刻薄的话，比碎玻璃更伤人。",""],[72,69,"publish","/ˈpʌbliʃ/",[["v","出版，发行；公布，发布"]],[],"","v.","出版；发布","She published her first poem at seventeen.","她十七岁时发表了第一首诗。",""],[73,68,"focus","/ˈfəukəs/",[["n","焦点"],["v","聚焦在，集中注意力于"]],[],"","v.","集中；n. 焦点","Focus on the step in front of you.","专注于眼前的这一步。",""],[74,68,"affect","/əˈfekt/",[["v","影响；感动，打动"]],[],"","v.","影响；打动","Music affects the heart before the mind.","音乐先打动心，再抵达头脑。",""],[75,65,"feed","/fiːd/",[["v","喂养；供给食物"]],[],"","v.","喂养；满足","Feed your curiosity, and it will feed you back.","喂饱你的好奇心，它会回馈你。",""],[76,65,"weigh","/wei/",[["v","重量是；称（重量），重达；权衡，考虑"]],[],"","v.","权衡；重达","Weigh your words; they travel farther than you.","掂量你的话语，它们走得比你更远。",""],[77,64,"pressure","/ˈpreʃə/",[["n","压力，压强；心理压力"]],[],"","n.","压力","Diamonds are made under pressure, but so is coal.","压力下能造出钻石，也能造出煤炭。",""],[78,64,"credit","/ˈkredɪt/",[["n","信用；学分，赞扬，信誉"],["v","相信；把钱存入（账户）"]],[],"","n.","赞扬；学分；信用","Give yourself credit for how far you've come.","为你走过的路，给自己一点赞许。",""],[79,64,"visible","/ˈvizəbl/",[["adj","可见的；明显的，显而易见的"]],[],"","adj.","看得见的；明显的","Work is love made visible.","工作是看得见的爱。","纪伯伦"],[80,63,"operate","/ˈɔpəreit/",[["v","操作，经营，动手术；运转，运作"]],[],"","v.","运转；操作","The old clock still operates without a sound.","那台老钟依然在无声地运转。",""],[81,62,"warn","/wɔːn/",[["v","警告；提醒"]],[],"","v.","警告；提醒","The red sky at night warns of nothing but beauty.","夜晚的红霞，只提醒着美。",""],[82,60,"relate","/riˈleit/",[["v","有关联（to），陈述"]],[],"","v.","与…有关；联系","Everyone can relate to the fear of a blank page.","面对空白的纸页时的害怕，人人都懂。",""],[83,60,"strength","/streŋθ/",[["n","力量，（精神）力量；优势，强项"]],[],"","n.","力量；长处","Gentleness is a kind of strength.","温柔也是一种力量。",""],[84,60,"stress","/stres/",[["v","强调"],["n","压力，强调"]],[],"","n.","压力；v. 强调","A walk in the park can melt the day's stress.","去公园散个步，能化开一天的压力。",""],[85,60,"attack","/əˈtæk/",[["n","攻击；（疾病的）发作；侵袭；（情感的）一阵突发"],["v","攻击；批评，抨击"]],[],"","n.","攻击；（病）发作","A sudden attack of the giggles ruined our serious photo.","一阵突然的傻笑，毁了我们的严肃合照。",""],[86,60,"determine","/diˈtəːmin/",[["v","下决心；决定、确定（事实、原因等）"]],[],"","v.","决定；下决心","Determine what you want, then begin.","想清楚你要什么，然后开始。",""],[87,60,"volunteer","/vɔlənˈtiə/",[["n","志愿者"],["v","（自愿）做"]],[],"","v.","自愿做；n. 志愿者","She volunteers at the library every Saturday.","她每周六都去图书馆做志愿者。",""],[88,59,"lack","/læk/",[["n","缺乏；不足之处"],["v","缺乏（of/in）"]],[],"","v.","缺乏；n. 不足","The desert lacks rain, not beauty.","沙漠缺少的是雨水，而不是美。",""],[89,59,"equipment","/iˈkwipmənt/",[["n","设备；配备；装备"]],[],"","n.","设备；装备","The only equipment you need to dream is time.","做梦唯一需要的装备，是时间。",""],[90,58,"expense","/iksˈpens/",[["n","花费；费用、开销"]],[],"","n.","费用；开销","Friendship is never an expense; it's an investment.","友谊从不是一笔开销，而是一种投资。",""],[91,58,"deliver","/diˈlivə/",[["v","递送，传递；发表（演讲）；交付；助产，接生"]],[],"","v.","递送；发表","The wind delivers seeds to distant fields.","风把种子送往遥远的田野。",""],[92,57,"compare","/kəmˈpeə(r)/",[["v","比较（with）；对照；比喻（to）"]],[],"","v.","比较；比作","Shall I compare thee to a summer's day?","我能否将你比作夏日？","莎士比亚"],[93,57,"spread","/spred/",[["v","延伸，传播；扩散；涂抹（如涂抹黄油）"]],[],"","v.","传播；展开","Good news spreads like the smell of fresh bread.","好消息像新烤面包的香气一样传开。",""],[94,57,"seek","/siːk/",[["v","寻找；探求；追求"]],[],"","v.","寻找；追求","To strive, to seek, to find, and not to yield.","去奋斗，去探索，去寻找，永不屈服。","丁尼生"],[95,56,"distant","/ˈdistənt/",[["adj","遥远的；远处的；冷淡的，疏远的"]],[],"","adj.","遥远的；疏远的","A true friend far away makes the distant world feel near.","海内存知己，天涯若比邻。","王勃"],[96,56,"original","/əˈridʒənl/",[["adj","原始的，最初的；原创的"]],[],"","adj.","原创的；最初的","Be an original; the world has enough copies.","做原创的自己，世界的复制品已经够多了。",""],[97,55,"impress","/imˈpres/",[["v","给…留下深刻的好印象；影响；打动（on/upon）"]],[],"","v.","给…深刻印象","Don't try to impress; try to understand.","别急着打动别人，试着去理解。",""],[98,54,"remind","/riˈmaind/",[["v","提醒（of）；使......想起（of/about）"]],[],"","v.","提醒；使想起","Lives of great men all remind us we can make our lives sublime.","伟人的一生提醒我们，我们也能让生命崇高。","朗费罗"],[99,54,"communicate","/kəˈmjuːnɪkeɪt/",[["v","交流（with）；沟通；传达"]],[],"","v.","交流；传达","Animals communicate without a single word.","动物们不用一句话，也能交流。",""],[100,52,"range","/reindʒ/",[["n","范围，系列"],["v","变化范围；排列；漫游（from...to...）"]],[],"","n.","范围；系列","The mountain range turned gold at sunset.","日落时，群山染成了金色。",""],[101,52,"guidance","/ˈgaidəns/",[["n","指导；引导；指引"]],[],"","n.","指导；引导","Good guidance shows the door; you must walk through it.","好的指引只是指出那扇门，走进去要靠你自己。",""],[102,51,"avoid","/əˈvɔid/",[["v","避免；躲避"]],[],"","v.","避免；躲避","You can avoid reality, but not its consequences.","你可以逃避现实，却逃不开它的后果。",""],[103,51,"opportunity","/ˌɔpəˈtjuːniti/",[["n","机会；时机"]],[],"","n.","机会；时机","Every exam is also an opportunity to learn.","每一场考试，也是一次学习的机会。",""],[104,51,"emotion","/iˈməuʃən/",[["n","情绪；情感"]],[],"","n.","情感；情绪","Name your emotions, and they grow quieter.","给情绪起个名字，它们就会安静下来。",""],[105,50,"equal","/ˈiːkwəl/",[["adj","相等的；平等的"],["v","等于；比得上 （to）"]],[],"","adj.","相等的；平等的","There is no charm equal to tenderness of heart.","没有一种魅力，比得上心地的温柔。","简·奥斯汀"],[106,50,"contain","/kənˈtein/",[["v","包含；容纳；控制"]],[],"","v.","包含；容纳","I am large, I contain multitudes.","我辽阔广大，我包罗万象。","惠特曼"],[107,50,"hardly","/ˈhɑːdli/",[["adv","几乎不；简直不"]],[],"","adv.","几乎不","I could hardly believe the sky was that color.","我简直不敢相信，天空会是那种颜色。",""],[108,48,"announce","/əˈnauns/",[["v","宣布；通告"]],[],"","v.","宣布；通告","The birds announce the morning long before the alarm.","闹钟还没响，鸟儿就已宣告清晨。",""],[109,48,"reward","/riˈwɔːd/",[["v","奖赏；酬谢"],["n","奖励；报酬"]],[],"","n.","奖励；报酬","The reward for good work is more good work.","做好一件事的奖励，是更多值得做的事。",""],[110,48,"desire","/diˈzaiə/",[["n","渴望；欲望"],["v","渴望；希望"]],[],"","n.","渴望；v. 希望","Desire lights the road; discipline walks it.","渴望照亮道路，自律走完它。",""],[111,47,"promote","/prəˈməut/",[["v","促进；促销；推广；升迁；晋升"]],[],"","v.","促进；提升","Sleep promotes memory more than late-night cramming.","睡眠比熬夜突击，更能促进记忆。",""],[112,47,"gather","/ˈgæðə/",[["v","聚集；收集"],["n","聚集；集会"]],[],"","v.","收集；聚集","Gather ye rosebuds while ye may.","及时采撷你的玫瑰花蕾。","罗伯特·赫里克"],[113,47,"similarity","/ˌsimiˈlæriti/",[["n","相似，类似；类似之处"]],[],"","n.","相似之处","Look for similarities, not just differences.","多看看相似之处，而不只是差异。",""],[114,46,"advance","/ədˈvɑːns/",[["n","进步，提升；预付款"],["v","推进，提升"]],[],"","v.","前进；n. 进步","If one advances confidently in the direction of his dreams…","如果一个人自信地朝着梦想的方向前进……","梭罗"],[115,46,"percent","/pəˈsent/",[["n","百分比；百分率"]],[],"","n.","百分比","Give one hundred percent, then let it go.","全力以赴，然后放下。",""],[116,46,"character","/ˈkæriktə/",[["n","性格；特性；人物；角色"]],[],"","n.","性格；角色","Character shows in the smallest choices.","品格，藏在最小的选择里。",""],[117,45,"frighten","/ˈfraitən/",[["v","使惊吓；使害怕"]],[],"","v.","使害怕；吓唬","Thunder frightens the dog, but not the old oak.","雷声吓坏了小狗，却吓不倒老橡树。",""],[118,44,"accessible","/ækˈsesəbl/",[["adj","易接近的；可进入的；可理解的"]],[],"","adj.","易接近的；可进入的","Good teachers make hard ideas accessible.","好老师能让难懂的道理变得易懂。",""],[119,44,"potential","/pəˈtenʃəl/",[["adj","潜在的；可能的"],["n","潜力；潜能"]],[],"","n.","潜力；adj. 潜在的","Every acorn holds the potential of a forest.","每一颗橡果，都藏着一片森林的潜力。",""],[120,44,"review","/riˈvjuː/",[["v","复习；回顾；评论"],["n","评论；回顾；复习"]],[],"","v.","复习；回顾","Review a little every day, and June won't scare you.","每天复习一点，六月就不会吓到你。",""],[121,43,"replace","/riˈpleis/",[["v","取代；替换"]],[],"","v.","代替；替换","Nothing can replace an honest conversation.","什么也替代不了一次坦诚的谈话。",""],[122,43,"greedy","/ˈgriːdi/",[["adj","贪婪的；贪心的"]],[],"","adj.","贪心的；贪婪的","Be greedy for knowledge, generous with kindness.","对知识贪心一点，对善意慷慨一点。",""],[123,43,"shock","/ʃɔk/",[["n","震惊，冲击；电击；令人震惊的事"],["v","使震惊；使受冲击"]],[],"","n.","震惊；冲击","The cold water was a pleasant shock on a hot day.","大热天里，冷水带来一阵舒爽的冲击。",""],[124,42,"judge","/dʒʌdʒ/",[["v","判断；评判"],["n","法官，裁判"]],[],"","v.","评判；n. 法官","Don't judge a book by its cover.","不要以貌取人。","英语谚语"],[125,42,"praise","/preiz/",[["n","称赞；赞美"],["v","称赞；赞美"]],[],"","n.","赞扬；v. 称赞","Praise the effort, not just the result.","称赞努力，而不只是结果。",""],[126,42,"recover","/riˈkʌvə/",[["v","恢复；康复"]],[],"","v.","恢复；康复","Rest is how strong people recover.","休息，是强者恢复的方式。",""],[127,42,"confuse","/kənˈfjuːz/",[["v","使困惑；混淆"]],[],"","v.","使困惑；混淆","Don't confuse being busy with being productive.","别把忙碌和高效混为一谈。",""],[128,42,"spot","/spɒt/",[["n","地点；斑点"],["v","发现；认出"]],[],"","v.","发现；n. 地点","We spotted a rainbow on the way home.","回家的路上，我们发现了一道彩虹。",""],[129,42,"attempt","/əˈtempt/",[["v","企图，尝试"],["n","尝试；努力"]],[],"","n.","尝试；v. 企图","Our doubts are traitors, and make us lose the good we oft might win by fearing to attempt.","疑虑是叛徒，让我们因不敢尝试，而失去本可赢得的美好。","莎士比亚"],[130,42,"available","/əˈveiləbl/",[["adj","可用的；可得到的"]],[],"","adj.","可用的；有空的","Use the time available, not the time you wish you had.","用好手头的时间，而不是你希望拥有的时间。",""],[131,42,"destruction","/diˈstrʌkʃən/",[["n","破坏，毁灭"]],[],"","n.","毁灭；破坏","After the storm's destruction, the first green shoots appeared.","风暴过后的废墟里，冒出了第一抹新绿。",""],[132,41,"construct","/kənˈstrʌkt/",[["v","建造，构造"]],[],"","v.","建造；构造","Birds construct their nests one twig at a time.","鸟儿一根枝条一根枝条地筑巢。",""],[133,41,"function","/ˈfʌŋkʃən/",[["n","功能；作用"],["v","起作用；运行"]],[],"","v.","运行；n. 功能","The brain functions best after a good night's sleep.","睡好一夜之后，大脑运转得最好。",""],[134,41,"argument","/ˈɑːgjumənt/",[["n","论点；争论，辩论；争吵"]],[],"","n.","论点；争论","A good argument needs evidence, not volume.","好的论点需要证据，而不是音量。",""],[135,40,"labor","/ˈleibə/",[["n","劳力；劳动"]],[],"","n.","劳动；劳力","The bread tastes better when it's your own labor.","自己劳动换来的面包，格外香甜。",""],[136,40,"private","/ˈpraivit/",[["adj","私人的，秘密的"]],[],"","adj.","私人的；秘密的","Everyone needs a private corner to think.","每个人都需要一个可以独自思考的角落。",""],[137,40,"repeat","/riˈpiːt/",[["v","重复；复述"]],[],"","v.","重复；复述","Repeat a word ten times, and it becomes yours.","把一个单词重复十遍，它就属于你了。",""],[138,40,"spirit","/ˈspɪrɪt/",[["n","精神；心灵；（某种类型的）人【前需加形容词】；勇气；志气；意志；活力；心态；态度【只用单数】；灵魂；鬼魂，幽灵；【U】真实意义，实质；情绪，心境【只用复数】"]],[],"","n.","精神；心灵","The spirit grows in small acts of courage.","精神，在一次次小小的勇敢中成长。",""],[139,40,"suppose","/səˈpəʊz/",[["v","（根据所知）认为，推断，料想；假定，假设，设想；我看，要我说，我想"]],[],"","v.","认为；假定","Never suppose you know someone completely.","永远别以为你完全了解一个人。",""],[140,40,"desert","/ˈdezətˌdiˈzəːt/",[["n","/ˈdezət/ 沙漠；荒漠；荒原"],["v","/dɪˈzɜːt /抛弃，离弃，遗弃（某人）；舍弃，离弃（某地方）；擅离（部队）；逃走"]],[],"","n.","沙漠；v. 抛弃","What makes the desert beautiful is that somewhere it hides a well.","沙漠之所以美，是因为它在某处藏着一口井。","圣埃克苏佩里"],[141,39,"exchange","/iksˈtʃeindʒ/",[["n","（学生﹑教师等的）互访，交换；交换；交流；兑换；汇兑"],["v","交换；互换；兑换；汇兑"]],[],"","v.","交换；n. 交流","Exchange ideas, not insults.","交流观点，而不是交换恶语。",""],[142,39,"fairly","/ˈfɛəli/",[["adv","公正地，相当地"]],[],"","adv.","相当地；公平地","The test was fairly hard, but fairly marked.","这次考试挺难，但评分很公平。",""],[143,39,"regret","/riˈgret/",[["v","后悔（做了某事）；对…感到遗憾"],["n","懊悔，悔恨；遗憾；惋惜"]],[],"","v.","后悔；遗憾","You'll rarely regret the times you were kind.","你很少会后悔自己善良的时候。",""],[144,39,"strict","/strɪkt/",[["adj","严格的，严厉的"]],[],"","adj.","严格的；严厉的","A strict teacher is often a caring one.","严格的老师，往往是用心的老师。",""],[145,39,"fellow","/ˈfeləu/",[["adj","同类的；同事的；同伴的；同情况的"],["n","同事，家伙；伙伴"]],[],"","adj.","同伴的；n. 伙伴","Smile at your fellow travelers.","对同行的旅人笑一笑吧。",""],[146,39,"gradually","/ˈgrædjuəli/",[["adv","逐渐地；渐进地"]],[],"","adv.","逐渐地","The Truth must dazzle gradually, or all the world be blind.","真理必须渐渐闪耀，否则世人都会目盲。","艾米莉·狄金森"],[147,39,"belief","/biˈliːf/",[["n","信心，信念，信仰"]],[],"","n.","信念；信仰","Belief in yourself is the first step.","相信自己，是第一步。",""],[148,39,"imagination","/iˌmædʒiˈneiʃən/",[["n","想象力"]],[],"","n.","想象力","Imagination is more important than knowledge.","想象力比知识更重要。","爱因斯坦"],[149,39,"official","/əˈfiʃəl/",[["adj","正式的；官方的"],["n","官员"]],[],"","adj.","正式的；官方的","It's official: summer has arrived.","正式宣布：夏天到了。",""],[150,38,"account","/əˈkaunt/",[["n","叙述，描写，报道；账户；账单；（公司的）账目 【只用复数】"],["v","（+for） 占（一定数量或比例）；是…的原因；解释，说明"]],[],"","n.","叙述；账户","Her account of the trip made us all laugh.","她讲述的旅行经历，把我们都逗笑了。",""],[151,38,"persuade","/pəˈsweid/",[["v","说服；使信服"]],[],"","v.","说服","You can't persuade a cat to do anything.","你没法说服一只猫做任何事。",""],[152,38,"figure","/ˈfigə/",[["n","人物；数字；（隐约可见的）人影；身材；体形；图形"],["v","认为，认定（某事将发生或属实）"]],[],"","n.","身影；数字；人物","A small figure waved from the top of the hill.","山顶上，一个小小的身影在挥手。",""],[153,38,"seldom","/ˈseldəm/",[["adv","很少；不常"]],[],"","adv.","很少；不常","Opportunity seldom knocks twice.","机不可失，时不再来。","英语谚语"],[154,38,"eager","/ˈiːgə/",[["adj","渴望的；热切的"]],[],"","adj.","渴望的；热切的","Eager minds learn fast.","求知若渴的头脑，学得很快。",""],[155,37,"recommend","/ˌrekəˈmend/",[["v","推荐，建议"]],[],"","v.","推荐；建议","I recommend a book over a screen before bed.","睡前，我推荐看书而不是刷屏。",""],[156,37,"remove","/riˈmuːv/",[["v","移除；去除；搬迁；开除；摘掉；脱掉"]],[],"","v.","移除；去除","Remove one distraction, and you gain an hour.","去掉一个干扰，你就多出一个小时。",""],[157,37,"unique","/juːˈniːk/",[["adj","独一无二的；独特的；罕见的"]],[],"","adj.","独特的；独一无二的","No two snowflakes are alike; each is unique.","没有两片雪花相同，每一片都独一无二。",""],[158,37,"risk","/risk/",[["v","冒...的危险；冒险"],["n","危险，风险"]],[],"","v.","冒险；n. 风险","To grow, you must risk being a beginner again.","想要成长，就得冒险重新做回新手。",""],[159,37,"economic","/ˌiːkəˈnɔmik/",[["adj","经济的；经济学的"]],[],"","adj.","经济的；经济学的","Walking is the most economic way to see a city.","步行，是看一座城市最经济的方式。",""],[160,36,"pollution","/pəˈluːʃən/",[["n","污染；污染物；环境污染"]],[],"","n.","污染","Light pollution hides the stars from the city.","光污染，把星星从城市的夜空藏了起来。",""],[161,36,"literature","/ˈlitərətʃə/",[["n","文学；文献"]],[],"","n.","文学；文献","Literature lets us live a thousand lives.","文学让我们活过一千种人生。",""],[162,36,"consume","/kənˈsjuːm/",[["v","消耗，消费；（使）沉溺，（使）沉迷，（使）充满（感情或思想）"]],[],"","v.","消耗；吞噬","Worry consumes the energy you need for action.","担忧会消耗你行动所需的力气。",""],[163,36,"stick","/stɪk/",[["v","粘住，坚持；将…刺入（或插入）；刺；戳；插入"],["n","条状物；棍状物；（木料或塑料制成的有特定用途的）棍，条，签"]],[],"","v.","坚持；粘贴","Stick with it, even when it's boring.","即使枯燥，也要坚持下去。",""],[164,36,"devote","/diˈvəut/",[["v","致力于；奉献"]],[],"","v.","致力于；奉献","Like the spring silkworm, she devoted herself until her last thread.","春蚕到死丝方尽。","李商隐"],[165,35,"predict","/priˈdikt/",[["v","预言；预测"]],[],"","v.","预测；预言","No one can predict every question, so learn them all.","没人能押中每道题，那就全都学会。",""],[166,35,"complain","/kəmˈpleɪn/",[["v","抱怨；诉苦"]],[],"","v.","抱怨","Complain less, notice more.","少一点抱怨，多一点留意。",""],[167,35,"annoy","/əˈnɔi/",[["v","使恼怒，使生气；打扰，骚扰"]],[],"","v.","使恼怒；打扰","Small noises annoy us most when we're tired.","人累的时候，最容易被小声音惹恼。",""],[168,35,"apply","/əˈplai/",[["v","应用；申请；涂抹"]],[],"","v.","申请；应用；涂抹","Knowledge is power only when you apply it.","知识只有被运用时，才是力量。",""],[169,35,"handle","/ˈhændl/",[["v","处理；操作"],["n","把手；手柄"]],[],"","v.","处理；n. 把手","Handle hard days gently.","温柔地对待难熬的日子。",""],[170,35,"object","/əbˈdʒekt/",[["v","反对（to）"],["n","目标，物体；对象"]],[],"","n.","物体；对象；v. 反对","The telescope turned a tiny object into a whole world.","望远镜把一个小点，变成了一个完整的世界。",""],[171,35,"select","/siˈlekt/",[["v","挑选；选择"]],[],"","v.","挑选；选择","Select your friends as you select your books: with care.","像挑书一样，用心挑选朋友。",""],[172,35,"opposite","/ˈɔpəzit/",[["adj","相反的，对立的，对面的"]],[],"","adj.","相反的；对面的","The opposite of fear is not courage, but curiosity.","恐惧的反面不是勇气，而是好奇。",""],[173,35,"solution","/səˈluːʃən/",[["n","解决办法；溶液；溶解（过程）"]],[],"","n.","解决办法；溶液","Sometimes the solution is simply a walk outside.","有时候，解决办法就是出门走一走。",""],[174,34,"struggle","/ˈstrʌɡl/",[["n","斗争；挣扎；奋斗，拼搏"],["v","斗争；挣扎；奋斗，拼搏"]],[],"","v.","奋斗；挣扎","The butterfly must struggle out of its shell to fly.","蝴蝶必须挣扎着破茧，才能飞翔。",""],[175,34,"approach","/əˈprəutʃ/",[["v","靠近；着手处理，对付；建议，要求"],["n","途径，方法（to）"]],[],"","v.","靠近；n. 方法","Approach every problem like a curious child.","像个好奇的孩子那样，去面对每一个问题。",""],[176,34,"urgent","/ˈəːdʒənt/",[["adj","紧急的；迫切的"]],[],"","adj.","紧急的；迫切的","Not everything urgent is important.","并不是所有紧急的事都重要。",""],[177,34,"delight","/diˈlait/",[["n","高兴；愉快"],["v","使高兴；使愉快"]],[],"","v.","使高兴；n. 乐事","Forget not that the earth delights to feel your bare feet.","别忘了，大地喜欢感受你赤裸的双脚。","纪伯伦"],[178,33,"talent","/ˈtælənt/",[["n","天赋；才能 【U】 有才能的人，天才【U】"]],[],"","n.","天赋；才能","Heaven gave me talent, and it must be of use.","天生我材必有用。","李白"],[179,33,"track","/træk/",[["v","跟踪；追踪"],["n","小路；轨道；跑道；田径运动"]],[],"","n.","小路；轨道；v. 追踪","Keep on track, even when the track is muddy.","即使路途泥泞，也别偏离轨道。",""],[180,33,"arrange","/əˈreindʒ/",[["v","安排；整理；改编（乐曲）"]],[],"","v.","安排；整理","She arranged the flowers by color, like a rainbow.","她按颜色插花，像一道彩虹。",""],[181,33,"wealth","/welθ/",[["n","财富；财产"]],[],"","n.","财富；财产","The first wealth is health.","健康是第一财富。","爱默生"],[182,33,"security","/siˈkjuːriti/",[["n","安全；保障；安保措施"]],[],"","n.","安全；保障","A warm home gives children a sense of security.","温暖的家，给孩子安全感。",""],[183,32,"entire","/inˈtaiə/",[["adj","全部的；整个的"]],[],"","adj.","整个的；全部的","One candle can light an entire room.","一支蜡烛，能照亮整个房间。",""],[184,32,"positive","/ˈpɔzitiv/",[["adj","积极的；肯定的"]],[],"","adj.","积极的；肯定的","A positive mind finds a way; a negative one finds an excuse.","积极的心找办法，消极的心找借口。",""],[185,32,"rarely","/ˈrɛəli/",[["adv","很少；难得；罕见地"]],[],"","adv.","很少；难得","The truth is rarely pure and never simple.","真相很少纯粹，也从不简单。","王尔德"],[186,32,"reflect","/riˈflekt/",[["v","反射，反映；深思"]],[],"","v.","反射；反映；深思","The lake reflects the mountains like a mirror.","湖面像镜子一样，映出群山。",""],[187,32,"contact","/ˈkɔntækt/",[["v","接触，联系"],["n","接触，联系"]],[],"","v.","联系；n. 接触","Stay in contact with old friends; they remember who you were.","和老朋友保持联系，他们记得你从前的样子。",""],[188,32,"hesitate","/ˈheziteit/",[["v","犹豫；踌躇"]],[],"","v.","犹豫","He who hesitates is lost.","犹豫不决，必失良机。","英语谚语"],[189,31,"permit","/pəˈmit/",[["v","允许；许可"],["n","许可证；执照"]],[],"","v.","允许；n. 许可证","Weather permitting, we'll climb the hill at dawn.","天气允许的话，我们黎明去爬山。",""],[190,30,"rapid","/ˈræpid/",[["adj","迅速的；快速的；急速的"]],[],"","adj.","迅速的；快速的","Rapid progress often follows a long, slow start.","迅速的进步，往往跟在漫长缓慢的起步之后。",""],[191,30,"colleague","/ˈkɒliːɡ/",[["n","同事；同僚"]],[],"","n.","同事","Good colleagues make Monday mornings lighter.","好同事让周一的早晨变得轻松。",""],[192,30,"conclude","/kənˈkluːd/",[["v","总结；结束；得出结论"]],[],"","v.","得出结论；结束","The concert concluded with a quiet song.","音乐会以一首安静的歌结束。",""],[193,30,"host","/həust/",[["n","主人，主持人"],["v","主办，主持"]],[],"","v.","主持；n. 主人","The old tree hosts a hundred birds each spring.","每年春天，那棵老树都招待上百只鸟。",""],[194,30,"version","/ˈvəːʃən/",[["n","版本；译本；变体"]],[],"","n.","版本","Be the best version of yourself, not a copy of someone else.","做最好版本的自己，而不是别人的复制品。",""],[195,29,"accommodation","/əˌkɔməˈdeiʃn/",[["n","住处，住宿；膳宿"]],[],"","n.","住处；住宿","The cottage offers simple accommodation and a view of the sea.","这间小屋提供简朴的住处，和一片海景。",""],[196,29,"possess","/pəˈzes/",[["v","拥有；具有；支配，控制"]],[],"","v.","拥有；具有","Happiness is not in what we possess, but in what we share.","幸福不在于拥有什么，而在于分享什么。",""],[197,29,"collection","/kəˈlekʃn/",[["n","收集；收藏品；系列"]],[],"","n.","收藏；收集","My shell collection holds a hundred summers.","我收集的贝壳里，装着一百个夏天。",""],[198,29,"survive","/səˈvaɪv/",[["v","幸存；幸存；比......活得长"]],[],"","v.","幸存；挺过","Wild grass survives the fire and grows again in spring.","野火烧不尽，春风吹又生。","白居易"],[199,29,"feature","/ˈfiːtʃə(r)/",[["n","特征；特色"],["v","以…为特色，是…的特征；是…的重要组成部分"]],[],"","n.","特征；特色","The most beautiful feature of the town is its old bridge.","小镇最美的地方，是那座老桥。",""],[200,29,"appreciate","/əˈpriːʃieit/",[["v","欣赏，感激；感谢；意识到；理解，明白；增值，升值"]],[],"","v.","欣赏；感激","Appreciate the small things; one day they'll be the big things.","珍惜小事，总有一天它们会成为大事。",""],[201,29,"embarrass","/imˈbærəs/",[["v","使尴尬；使局促不安"]],[],"","v.","使尴尬；使局促","Mistakes embarrass us only until they teach us.","错误让人难堪，直到它教会我们什么。",""],[202,28,"profit","/ˈprɔfit/",[["n","利润，经济收益"],["v","获利，从中受益"]],[],"","v.","受益；n. 利润","We profit most from the lessons we didn't want.","我们往往从不想要的教训里，获益最多。",""],[203,28,"ancient","/ˈeinʃənt/",[["adj","古老的；来自古代的"]],[],"","adj.","古老的","Ancient light from dead stars still reaches our eyes.","早已熄灭的星星，它们古老的光依然抵达我们眼中。",""],[204,28,"historical","/hisˈtɔːrikəl/",[["adj","历史的；有关历史的；基于历史的"]],[],"","adj.","历史的","Every old street has a historical whisper.","每一条老街，都有历史的低语。",""],[205,28,"victim","/ˈviktim/",[["n","受害者；牺牲品；受害物"]],[],"","n.","受害者；牺牲品","Don't be a victim of your own excuses.","别成为自己借口的受害者。",""],[206,28,"broaden","/ˈbrɔːdn/",[["v","扩大；拓宽；增宽"]],[],"","v.","拓宽；扩大","Read ten thousand books, travel ten thousand miles, and broaden your world.","读万卷书，行万里路。","古语"],[207,27,"plastic","/ˈplæstik/",[["n","塑料；塑性材料"],["adj","可塑的；塑性的；塑料制的"]],[],"","n.","塑料；adj. 塑料的","A plastic bag can drift in the sea for centuries.","一只塑料袋，能在海里漂流好几百年。",""],[208,27,"primary","/ˈpraiməri/",[["adj","主要的；首要的；最初的；基本的"]],[],"","adj.","首要的；主要的","Your primary job today is to rest.","你今天的首要任务，是休息。",""],[209,27,"reaction","/riˈækʃən/",[["n","反应；回应"]],[],"","n.","反应；回应","For every action, there is an equal and opposite reaction.","每一个作用力，都有一个大小相等、方向相反的反作用力。","牛顿第三定律"],[210,27,"represent","/ˌrepriˈzent/",[["v","代表；象征；表现；描绘"]],[],"","v.","代表；象征","In many cultures, the olive branch represents peace.","在许多文化里，橄榄枝象征和平。",""],[211,27,"response","/riˈspɔns/",[["n","反应，回应；响应（to）"]],[],"","n.","回应；答复","Silence is sometimes the wisest response.","沉默，有时是最明智的回应。",""],[212,27,"surround","/səˈraʊnd/",[["v","包围；环绕"]],[],"","v.","环绕；包围","Let my love, like sunlight, surround you and yet give you illumined freedom.","让我的爱像阳光一样环绕你，又给你明亮的自由。","泰戈尔"],[213,27,"average","/ˈævəridʒ/",[["adj","平均的；普通的；平常的"],["n","平均数；平均水平；一般水准"]],[],"","adj.","普通的；平均的","An average day, done well, is a good day.","把平常的一天过好，就是美好的一天。",""],[214,27,"smooth","/smuːð/",[["v","使顺利，使光滑"],["adj","顺利的，光滑的"]],[],"","adj.","平稳的；光滑的","The course of true love never did run smooth.","真爱的道路，从来都不平坦。","莎士比亚"],[215,26,"cast","/kɑːst/",[["v","投掷；扔，掷，抛；投射（光、影子等）；分配（角色）；向…投以（视线、笑容等）"]],[],"","v.","投射（光、影）","The street lamp casts a long shadow on the snow.","路灯在雪地上投下长长的影子。",""],[216,26,"chemical","/ˈkemikəl/",[["adj","化学的"],["n","化学物质；化学制品"]],[],"","adj.","化学的；n. 化学品","Autumn is a slow chemical change painted in gold.","秋天是一场缓慢的化学变化，被涂成金色。",""],[217,26,"prison","/ˈprizn/",[["n","监狱；监禁"]],[],"","n.","监狱；牢笼","Fear builds a prison with no walls.","恐惧会造一座没有墙的牢笼。",""],[218,26,"purchase","/ˈpəːtʃəs/",[["v","购买"],["n","购买；购得的物品"]],[],"","v.","购买","You can purchase a book, but not the time to read it.","书可以买，读书的时间却买不到。",""],[219,26,"straight","/streɪt/",[["adj","直的；直率的；连续的"],["adv","笔直地，成直线地；平正地；连续地"]],[],"","adv.","径直；adj. 直的","Sit up straight, breathe, and begin.","坐直，深呼吸，然后开始。",""],[220,26,"switch","/swɪtʃ/",[["v","切换；转变；开关（操作）"],["n","（电路的）开关，闸，转换器；（尤指突然彻底的）改变，转变"]],[],"","v.","切换；n. 开关","Some days, just switch off and look at the sky.","有些日子，就关掉一切，看看天空吧。",""],[221,26,"treatment","/ˈtriːtmənt/",[["n","对待，待遇；治疗；处理"]],[],"","n.","对待；治疗","Laughter is a cheap and gentle treatment.","笑，是一种便宜又温和的疗法。",""],[222,26,"aware","/əˈwɛə/",[["adj","意识到的，明白的；注意到的；察觉到的"]],[],"","adj.","意识到的","Be aware of the small joys you usually miss.","留意那些你平时错过的小快乐。",""],[223,26,"narrow","/ˈnærəu/",[["adj","狭窄的"],["v","使变窄；缩小"]],[],"","adj.","狭窄的；v. 变窄","In the narrow alley, a cat napped in the sun.","窄巷里，一只猫在晒着太阳打盹。",""],[224,26,"hire","/ˈhaiə/",[["v","雇用；租用"]],[],"","v.","雇用；租用","Let's hire bikes and ride along the lake.","我们租几辆自行车，沿着湖边骑吧。",""],[225,26,"shoulder","/ˈʃəuldə/",[["n","肩膀"],["v","肩负；承担"]],[],"","n.","肩膀；v. 承担","If I have seen further, it is by standing on the shoulders of giants.","如果说我看得更远，那是因为我站在巨人的肩膀上。","牛顿"],[226,25,"content","/ˈkɔntentˌkənˈtent/",[["n","所容纳之物；所含之物；内容【复数名词】；（书、讲话、节目等的）内容；目录；（尤指食物或饮料中某物质的）含量"],["adj","满意的；满足的（with）"],["v","使满意；使满足"]],[],"","adj.","满足的；n. 内容","He who is content is rich.","知足者富。","老子"],[227,25,"contribute","/kənˈtribjuːt/",[["v","贡献；投稿；促成"]],[],"","v.","贡献；促成","Every voice contributes to the choir.","每一个声音，都在为合唱出力。",""],[228,25,"concept","/ˈkɒnsept/",[["n","概念；思想"]],[],"","n.","概念；观念","The concept of zero changed mathematics forever.","“零”这个概念，永远改变了数学。",""],[229,25,"concert","/ˈkɒnsət/",[["n","音乐会；演奏会"]],[],"","n.","音乐会","Rain on the roof is a free concert.","屋顶上的雨声，是一场免费的音乐会。",""],[230,25,"conflict","/ˈkɒnflɪkt/",[["n","冲突；矛盾；武装冲突"],["v","矛盾，冲突，抵触"]],[],"","n.","冲突；矛盾","Most conflict begins with not listening.","大多数冲突，都始于没有好好倾听。",""],[231,25,"decade","/ˈdekeid/",[["n","十年"]],[],"","n.","十年","A tree takes a decade to grow; a person takes a century.","十年树木，百年树人。","古语"],[232,25,"sincere","/sinˈsiə/",[["adj","真诚的；诚挚的"],["adj","真诚的；诚挚的；由衷的"]],[],"","adj.","真诚的","A sincere \"sorry\" can mend a lot.","一句真诚的“对不起”，能修补很多东西。",""],[233,24,"release","/riˈliːs/",[["v","释放；出版；发泄，释放情感"],["n","公开，发行，发布；新发行的东西；（尤指）新激光唱片，新电影；排放；泄漏；渗漏；解脱，轻松感"]],[],"","v.","释放；发布","Breathe in calm, release worry.","吸进平静，呼出担忧。",""],[234,24,"constant","/ˈkɔnstənt/",[["adj","持续不断的；不变的；连续的"]],[],"","adj.","持续的；不变的","Change is the only constant thing.","变化，是唯一不变的事。",""],[235,24,"conduct","/kənˈdʌkt/",[["v","实施；执行；指挥；引导"]],[],"","v.","指挥；实施","The wind conducts the trees like an orchestra.","风像指挥乐队一样，指挥着树木。",""],[236,24,"overcome","/ˌəuvəˈkʌm/",[["v","战胜，克服；压倒"],["v","战胜，克服；压倒；（某种情绪）控制…，对…产生极大的影响"]],[],"","v.","克服；战胜","What you overcome becomes part of your strength.","你克服过的困难，会成为你力量的一部分。",""],[237,23,"recycle","/riːˈsaikl/",[["v","循环利用；回收利用"]],[],"","v.","回收利用","Old jam jars recycle beautifully into lanterns.","旧果酱瓶，可以变身成漂亮的灯笼。",""],[238,23,"translate","/trænsˈleɪt/",[["v","翻译；转化；导致，造成；理解"]],[],"","v.","翻译；转化","Some feelings don't translate into words.","有些感受，无法翻译成文字。",""],[239,23,"fond","/fɔnd/",[["adj","喜欢的（of）；深情的，柔情的"]],[],"","adj.","喜爱的；深情的","Grandma was fond of singing while she cooked.","奶奶做饭的时候，总爱唱歌。",""],[240,23,"grateful","/ˈgreitfəl/",[["adj","感激的；感谢的"]],[],"","adj.","感激的","Be grateful for the teachers who were hard on you.","感激那些对你严格的老师吧。",""],[241,23,"guard","/gɑːd/",[["v","保护；防卫"],["n","守卫；警卫"]],[],"","v.","守护；n. 卫士","An old dog guards the sleeping village.","一只老狗，守护着沉睡的村庄。",""],[242,23,"motivate","/ˈməutiveit/",[["v","激发；激励"]],[],"","v.","激励；激发","Small wins motivate bigger efforts.","小小的胜利，会激励更大的努力。",""],[243,22,"pause","/pɔːz/",[["v","暂停；停止"],["n","暂停；间歇"]],[],"","v.","暂停；n. 停顿","Time flows like this river, never pausing day or night.","逝者如斯夫，不舍昼夜。","孔子"],[244,22,"celebrate","/ˈselibreit/",[["v","庆祝；赞美；颂扬；歌颂"]],[],"","v.","庆祝","Celebrate the progress, not just the finish line.","为进步庆祝，而不只是为终点。",""],[245,22,"trick","/trɪk/",[["v","欺骗；戏弄"],["n","诡计；戏法；技巧"]],[],"","n.","窍门；戏法","Little by little does the trick.","一点一点来，就能成事。","《伊索寓言》"],[246,22,"anxiety","/æŋˈzaiəti/",[["n","焦虑；忧虑"]],[],"","n.","焦虑","Write your anxiety down, and it becomes smaller.","把焦虑写下来，它就会变小。",""],[247,22,"debate","/diˈbeit/",[["v","辩论；讨论"],["n","辩论；讨论"]],[],"","n.","辩论；v. 讨论","A good debate ends in understanding, not victory.","好的辩论以理解收场，而不是胜负。",""],[248,22,"delay","/diˈlei/",[["v","延迟；推迟"],["n","延迟；耽搁"]],[],"","n.","延误；v. 推迟","Delay is the thief of time.","拖延是时间的窃贼。","英语谚语"],[249,22,"deserve","/diˈzəːv/",[["v","值得；应受"]],[],"","v.","值得；应得","You deserve the same kindness you give others.","你值得拥有你给别人的那份温柔。",""],[250,22,"schedule","/ˈskedʒul/",[["n","时间表；日常安排"],["v","安排，预定"]],[],"","n.","日程；时间表","Leave a blank space in your schedule for wonder.","在日程表里，给惊奇留一块空白。",""],[251,22,"specific","/spiˈsifik/",[["adj","特定的，具体的"]],[],"","adj.","具体的；特定的","Vague goals make vague days; be specific.","模糊的目标造就模糊的日子，要具体一点。",""],[252,21,"concentrate","/ˈkɔnsentreit/",[["v","专注，集中（on）"]],[],"","v.","专心；集中","Concentrate the light, and paper starts to burn.","把光聚在一点，纸就会燃烧。",""],[253,21,"quit","/kwit/",[["v","停止，辞职；放弃"]],[],"","v.","放弃；停止","Never quit on a hard day; decide on a calm one.","别在难熬的日子里放弃，等平静下来再做决定。",""],[254,21,"stare","/steə(r)/",[["v","凝视；盯着看"]],[],"","v.","凝视；盯着看","The cat stared at the rain as if it were a movie.","猫盯着雨看，像在看一场电影。",""],[255,21,"sympathy","/ˈsɪmpəθi/",[["n","同情；同感，共鸣；（尤指政治方面的）赞同，支持"]],[],"","n.","同情；共鸣","Sympathy is a small bridge between two hearts.","同情，是两颗心之间的一座小桥。",""],[256,21,"alternative","/ɔːlˈtəːnətiv/",[["adj","供选择的；替代的"],["n","替代选择；备选方案"]],[],"","n.","可选方案；adj. 替代的","Always keep an alternative route in mind.","心里永远留一条备选的路。",""],[257,21,"analyze","/ˈænəlaiz/",[["v","分析；解析"]],[],"","v.","分析","Analyze your mistakes, then forgive them.","分析你的错误，然后原谅它们。",""],[258,21,"ancestor","/ˈænsistə/",[["n","祖先；先辈"]],[],"","n.","祖先","Our ancestors read the seasons in the stars.","我们的祖先，从星星里读懂四季。",""],[259,21,"aspect","/ˈæspekt/",[["n","方面；观点；方位；（事物的）外观，样子，特征"]],[],"","n.","方面","Every aspect of a diamond catches a different light.","钻石的每一个切面，都捕捉着不同的光。",""],[260,21,"disability","/disəˈbiliti/",[["n","残疾；（某种）缺陷，障碍"]],[],"","n.","残疾；障碍","Beethoven wrote music despite his hearing disability.","贝多芬在听力残障之下，依然在作曲。",""],[261,20,"admire","/ədˈmaiə/",[["v","钦佩，羡慕，敬佩；欣赏，观赏"]],[],"","v.","钦佩；欣赏","I admire people who stay kind under pressure.","我欣赏那些在压力下依然善良的人。",""],[262,20,"adolescent","/ˌædəˈlesnt/",[["adj","青春期的"],["n","青少年"]],[],"","n.","青少年；adj. 青春期的","Every adolescent is a work in progress.","每个少年，都是一件正在完成的作品。",""],[263,20,"faithfully","/ˈfeiθfəli/",[["adv","忠实地；如实地，准确地；有规律地"]],[],"","adv.","忠实地","The tide returns faithfully, twice a day.","潮水每天两次，忠实地归来。",""],[264,20,"previous","/ˈpriːvjəs/",[["adj","以前的；早先的"]],[],"","adj.","以前的；先前的","Compare yourself only with your previous self.","只和从前的自己比较。",""],[265,20,"reliable","/riˈlaiəbl/",[["adj","可靠的；值得信赖的"]],[],"","adj.","可靠的","A reliable friend is like a lighthouse.","可靠的朋友，像一座灯塔。",""],[266,20,"legal","/ˈliːgəl/",[["adj","合法的，法律的"]],[],"","adj.","合法的；法律的","Fairness is more than what is legal.","公平，不止于合法。",""],[267,20,"compete","/kəmˈpiːt/",[["v","竞争；参加比赛"]],[],"","v.","竞争；比赛","Compete with yourself; it's the only fair race.","和自己竞争吧，那是唯一公平的比赛。",""],[268,20,"symbol","/ˈsɪmbl/",[["n","象征；标志；符号，记号"]],[],"","n.","象征；符号","In China, the plum blossom is a symbol of courage.","在中国，梅花是坚毅的象征。",""],[269,20,"trap","/træp/",[["n","陷阱，圈套；困境"],["v","困住；使陷入危险中；使陷入圈套"]],[],"","n.","陷阱；v. 困住","Some Cupid kills with arrows, some with traps.","丘比特杀人，有的用箭，有的用陷阱。","莎士比亚"],[270,20,"apologize","/əˈpɔlədʒaiz/",[["v","道歉，致歉（to sb for sth）"]],[],"","v.","道歉","Apologize quickly; forgive quickly too.","道歉要快，原谅也要快。",""],[271,20,"mistaken","/miˈsteikən/",[["adj","错误的"],["v","弄错"]],[],"","adj.","弄错的；错误的","I was mistaken, and that's how I learned.","我弄错了，也正是这样学会的。",""],[272,20,"vehicle","/ˈviːikl/",[["n","车辆，交通工具；（赖以表达思想、感情或达到目的的）手段，工具"]],[],"","n.","交通工具；载体","Language is a vehicle for thought.","语言是思想的载体。",""],[273,20,"brief","/briːf/",[["adj","短暂的，简短的，简洁的"]],[],"","adj.","短暂的；简短的","Cherry blossoms are brief, and that's why we look.","樱花短暂，所以我们才凝望。",""],[274,20,"sharp","/ʃɑːp/",[["adj","急剧的，锋利的，敏锐的"]],[],"","adj.","锋利的；敏锐的","A sword's sharp edge comes from grinding.","宝剑锋从磨砺出。","《警世贤文》"],[275,20,"ordinary","/ˈɔːdnri/",[["adj","平凡的，普通的"]],[],"","adj.","普通的；平凡的","Ordinary people do extraordinary things every day.","平凡的人，每天都在做着不平凡的事。",""],[276,19,"absorb","/əbˈsɔːb/",[["v","吸收，吞没；全神贯注"]],[],"","v.","吸收；吸引全神","The sponge absorbs water; the curious mind absorbs everything.","海绵吸水，好奇的头脑吸收一切。",""],[277,19,"ceremony","/ˈseriməni/",[["n","典礼；仪式"]],[],"","n.","典礼；仪式","Making tea can be a small, quiet ceremony.","泡一杯茶，也可以是一场安静的小仪式。",""],[278,19,"maintain","/meinˈtein/",[["v","维持；保持；坚持（意见）；维修，保养；供养；扶养"]],[],"","v.","保持；维持","It's easier to maintain a habit than to restart it.","保持一个习惯，比重新开始容易。",""],[279,19,"consequence","/ˈkɔnsikwəns/",[["n","后果；结果；重要性"]],[],"","n.","后果；结果","Every choice has a consequence; choose with care.","每个选择都有后果，要慎重。",""],[280,19,"citizen","/ˈsɪtɪzn/",[["n","市民；公民"]],[],"","n.","公民；市民","I am a citizen of the world.","我是世界公民。","第欧根尼"],[281,19,"violence","/ˈvaiələns/",[["n","暴力，暴行；（言语或反应的）愤怒，激烈"]],[],"","n.","暴力；猛烈","Gentle words achieve what violence never can.","温和的话语，能做到暴力永远做不到的事。",""],[282,19,"bid","/bid/",[["v","出价，投标；（为争取某物而作的）努力"]],[],"","v.","致意；出价","We bid farewell to summer with a last swim.","我们最后游了一次泳，向夏天道别。",""],[283,19,"bitter","/ˈbitə/",[["adj","苦的，痛苦的；愤愤不平的，充满怨恨的"]],[],"","adj.","苦的；痛苦的","Good medicine tastes bitter, but it heals.","良药苦口利于病。","古语"],[284,19,"shame","/ʃeim/",[["n","羞愧，耻辱；可耻的人或事物"]],[],"","n.","遗憾的事；羞耻","It's a shame to waste such a blue sky indoors.","这么蓝的天待在屋里，真是可惜。",""],[285,19,"bury","/ˈberi/",[["v","埋葬；掩埋；隐藏；把（感情或记忆）埋在心里:"]],[],"","v.","埋藏；隐藏","Squirrels bury more nuts than they remember.","松鼠埋下的坚果，比它们记得的多。",""],[286,18,"accurate","/ˈækjurit/",[["adj","精确的，，准确的，正确无误的"]],[],"","adj.","准确的；精确的","An accurate map is useful; a kind guide is better.","准确的地图很有用，热心的向导更好。",""],[287,18,"adapt","/əˈdæpt/",[["v","适应（to），调整；改编（for）"]],[],"","v.","适应；改编","Water adapts to every shape, yet stays water.","水适应任何形状，却依然是水。",""],[288,18,"regardless","/riˈgaːdlis/",[["adv","不顾的，不考虑的（of）"]],[],"","adv.","不管怎样","Keep going, regardless of the weather.","无论天气如何，都继续前进。",""],[289,18,"commercial","/kəˈmɜːʃl/",[["adj","商业的；贸易的；盈利的，为赚钱的"]],[],"","adj.","商业的","The old bookshop survived every commercial storm.","那家老书店，挺过了每一场商业风暴。",""],[290,18,"confidence","/ˈkɒnfɪdəns/",[["n","信心，信任；坚信，笃信；秘密，机密"]],[],"","n.","信心；信任","Confidence comes from preparation.","信心，来自准备。",""],[291,18,"amaze","/əˈmeiz/",[["v","使吃惊，使惊叹"]],[],"","v.","使惊叹","The universe never fails to amaze us.","宇宙总能让我们惊叹。",""],[292,18,"amuse","/əˈmjuːz/",[["v","娱乐，逗乐；使发笑"]],[],"","v.","逗乐；使发笑","Simple things amuse simple minds, and happy ones.","简单的事，能逗乐单纯的心，也能逗乐快乐的心。",""],[293,18,"attach","/əˈtætʃ/",[["v","附上，系上（to）；连接，使依恋"]],[],"","v.","附上；使依恋","Don't attach your worth to a single score.","别把你的价值，系在一个分数上。",""],[294,18,"typical","/ˈtipikəl/",[["adj","特有的，典型的；代表性的"]],[],"","adj.","典型的","A typical London day: four seasons before lunch.","典型的伦敦一天：午饭前就过完了四季。",""],[295,18,"negative","/ˈnegətiv/",[["adj","消极的，负面的；否定的；（结果）阴性的"]],[],"","adj.","消极的；负面的","Negative thoughts are clouds, not the sky.","消极的念头是云，不是天空。",""],[296,18,"species","/ˈspiːʃiːz/",[["n","物种，种类；（单复数形式相同）"]],[],"","n.","物种；种类","Bees help thousands of plant species survive.","蜜蜂帮助成千上万种植物生存。",""],[297,18,"occasion","/əˈkeiʒən/",[["n","场合，时机；特殊事件"]],[],"","n.","场合；时机","Rise to the occasion; you're more ready than you think.","迎难而上吧，你比自己以为的更有准备。",""],[298,17,"cautious","/ˈkɔːʃəs/",[["adj","谨慎的，小心的；慎重的"]],[],"","adj.","谨慎的；小心的","Be cautious with promises and generous with help.","许诺要谨慎，帮忙要慷慨。",""],[299,17,"engage","/inˈgeidʒ/",[["v","从事（in），参与；订婚，订约"]],[],"","v.","参与；吸引","Engage with the world, and it will engage with you.","你投入世界，世界也会回应你。",""],[300,17,"expose","/ikˈspəuz/",[["v","揭露，暴露（to）；使暴露于危险或不利条件中"]],[],"","v.","暴露；使接触","Expose yourself to new ideas, like plants to the sun.","让自己接触新想法，就像植物接触阳光。",""],[301,17,"political","/pəˈlitikəl/",[["adj","政治的"]],[],"","adj.","政治的","Man is by nature a political animal.","人天生是政治动物。","亚里士多德"],[302,17,"convenient","/kənˈviːnjənt/",[["adj","方便的；便利的"]],[],"","adj.","方便的；便利的","The convenient choice is not always the right one.","方便的选择，不一定是对的选择。",""],[303,17,"assess","/əˈses/",[["v","评定，评估"]],[],"","v.","评估；评定","Assess the situation before you rush in.","冲进去之前，先评估一下形势。",""],[304,17,"astonish","/əsˈtɔniʃ/",[["v","使惊讶，使吃惊"]],[],"","v.","使惊讶","The size of the ocean still astonishes me.","大海之辽阔，依然让我惊讶。",""],[305,17,"guarantee","/ˌgærənˈtiː/",[["v","保证"],["n","保证，担保"]],[],"","v.","保证；n. 担保","Hard work doesn't guarantee success, but laziness guarantees failure.","努力不保证成功，但懒惰一定导致失败。",""],[306,17,"decline","/diˈklain/",[["v","下降，衰退，拒绝"],["n","衰落，下降"]],[],"","v.","下降；婉拒","As the sun declines, the sky turns to peach.","太阳西沉，天空变成了蜜桃色。",""],[307,17,"background","/ˈbækgraund/",[["n","背景，出身背景；学历；经历"]],[],"","n.","背景","Birdsong played in the background of our call.","我们通话的背景里，有鸟在唱歌。",""],[308,17,"mysterious","/misˈtiəriəs/",[["adj","神秘的，不可思议的"]],[],"","adj.","神秘的","The most beautiful thing we can experience is the mysterious.","我们所能经历的最美的事物，是神秘。","爱因斯坦"],[309,17,"block","/blɔk/",[["n","街区；（方形或长方形）大块；立方体；长方体；大楼"],["v","阻塞；阻碍"]],[],"","n.","街区；块","Fear not the clouds that block your view; you stand on the highest floor.","不畏浮云遮望眼，自缘身在最高层。","王安石"],[310,17,"emergency","/iˈməːdʒənsi/",[["n","突发事件，紧急情况"]],[],"","n.","紧急情况","Keep calm; panic is the real emergency.","保持冷静，惊慌才是真正的紧急情况。",""],[311,17,"sink","/siŋk/",[["v","下沉（into），沉没；倒下；坐下"]],[],"","v.","下沉；沉入","The sun sinks slowly into the pink sea.","夕阳缓缓沉进粉色的海里。",""],[312,16,"abandon","/əˈbændən/",[["v","放弃，抛弃；遗弃"]],[],"","v.","放弃；抛弃","Abandon the habit, not the goal.","放弃坏习惯，而不是目标。",""],[313,16,"adjust","/əˈdʒʌst/",[["v","调节，调整，使适应（to）"]],[],"","v.","调整；适应","Adjust your pace, but keep your direction.","可以调整步伐，但别改变方向。",""],[314,16,"capital","/ˈkæpitl/",[["n","首都，资本"],["adj","大写的，资本的"]],[],"","n.","首都；资本","Paris was once the capital of artists and dreamers.","巴黎曾是艺术家和梦想家的首都。",""],[315,16,"charm","/tʃɑːm/",[["n","魅力，吸引力"]],[],"","n.","魅力；吸引力","Old towns have a quiet charm that new cities lack.","老城有一种新城市没有的安静魅力。",""],[316,16,"evaluate","/iˈvæljueit/",[["v","评价，评估"]],[],"","v.","评价；评估","Evaluate a day by the seeds you planted.","用你播下的种子，来评价这一天。",""],[317,16,"exploit","/ˈeksplɔit/",[["v","利用，开发；剥削"]],[],"","v.","利用；开发","Exploit the morning; your mind is freshest then.","好好利用早晨，那时头脑最清醒。",""],[318,16,"poison","/ˈpɔizən/",[["v","毒害"],["n","毒药，毒物"]],[],"","n.","毒药；v. 毒害","Comparison is a slow poison.","攀比是一种慢性毒药。",""],[319,16,"migrate","/ˈmaigreit/",[["v","迁移，迁徙"]],[],"","v.","迁徙；迁移","Swallows migrate south, but they always come back.","燕子南飞，却总会回来。",""],[320,16,"current","/ˈkʌrənt/",[["adj","现在的，当前的"],["n","水流；潮流；气流电流；思潮"]],[],"","adj.","当前的；n. 水流","Swim with the current when you can.","能顺流的时候，就顺流而游。",""],[321,16,"combine","/kəmˈbaɪn/",[["v","结合（with），联合"]],[],"","v.","结合；联合","Combine hard work with good rest.","把努力和好好休息结合起来。",""],[322,16,"sweep","/swiːp/",[["v","打扫，清扫；席卷，横扫"]],[],"","v.","清扫；席卷","A spring wind swept the clouds away.","一阵春风，把云彩一扫而空。",""],[323,16,"trade","/treɪd/",[["n","贸易，交易；行业"],["v","做生意，从事贸易；营业，营运"]],[],"","v.","交换；n. 贸易","I'd trade my umbrella for a little sunshine.","我愿意拿雨伞，换一点阳光。",""],[324,16,"appointment","/əˈpɔintmənt/",[["n","约会，预约；任命"]],[],"","n.","约会；预约","I have an appointment with the sunrise tomorrow.","明天，我和日出有个约会。",""],[325,16,"guilty","/ˈgilti/",[["adj","内疚的（of），有罪的；感到罪恶的"]],[],"","adj.","内疚的；有罪的","Don't feel guilty for taking a rest.","休息一下，不必内疚。",""],[326,16,"moral","/ˈmɔrəl/",[["adj","道德的；品行端正的"]],[],"","adj.","道德的；品行端正的","A moral compass works best in the dark.","道德的指南针，在黑暗中最管用。",""],[327,16,"wander","/ˈwɔndə/",[["v","漫步，闲逛；走神，心不在焉"]],[],"","v.","漫步；走神","I wandered lonely as a cloud that floats on high.","我独自漫游，像一朵高高飘浮的云。","华兹华斯"],[328,15,"charity","/ˈtʃæriti/",[["n","慈善，慈善机构；施舍"]],[],"","n.","慈善","Charity begins at home.","仁爱始于家。","英语谚语"],[329,15,"jog","/dʒɔg/",[["v","&"],["n","慢跑"]],[],"","v.","慢跑","Jog slowly; the point is to keep going.","慢慢跑，重点是不停下来。",""],[330,15,"ensure","/inˈʃuə/",[["v","确保，保证"]],[],"","v.","确保；保证","Good sleep ensures a clear head.","好的睡眠，确保头脑清醒。",""],[331,15,"poverty","/ˈpɔvəti/",[["n","贫困；贫穷"]],[],"","n.","贫穷；贫困","Poverty of spirit is the hardest kind.","精神上的贫乏，最难熬。",""],[332,15,"precise","/priˈsais/",[["adj","精确的；准确的"]],[],"","adj.","精确的；准确的","A watchmaker's hands are slow and precise.","钟表匠的手，缓慢而精准。",""],[333,15,"conservation","/ˌkɔnsəːˈveiʃən/",[["n","保护，保存；自然保护"]],[],"","n.","保护；保存","Conservation means thinking about grandchildren we'll never meet.","保护自然，就是为我们永远见不到的子孙着想。",""],[334,15,"consult","/kənˈsʌlt/",[["v","咨询，请教；商量"]],[],"","v.","请教；咨询","Consult your heart, then your calendar.","先问问你的心，再看看日程表。",""],[335,15,"crime","/kraɪm/",[["n","罪行；犯罪"]],[],"","n.","罪行；犯罪","Wasting a sunny Sunday should be a crime.","浪费一个晴朗的周日，应该算犯罪。",""],[336,15,"complex","/ˈkɒmpleks/",[["adj","复杂的；难懂的；费解的"],["n","（类型相似的）建筑群"]],[],"","adj.","复杂的","Complex problems are just simple ones holding hands.","复杂的问题，不过是简单问题手拉着手。",""],[337,15,"forbid","/fəˈbid/",[["v","禁止；不允许"]],[],"","v.","禁止","No law can forbid the heart to hope.","没有法律能禁止心去怀抱希望。",""],[338,15,"federal","/ˈfedərəl/",[["adj","联邦的；联邦政府的"]],[],"","adj.","联邦的","The federal park protects a thousand-year-old forest.","这座联邦公园，保护着一片千年古林。",""],[339,15,"gap","/gæp/",[["n","缺口，间隙；差距，分歧"]],[],"","n.","间隙；差距","Mind the gap between what you know and what you think you know.","留意你知道的，和你以为自己知道的之间的差距。",""],[340,15,"apparent","/əˈpærənt/",[["adj","明显的，，显而易见的"]],[],"","adj.","明显的","The answer becomes apparent once you stop rushing.","一旦你不再着急，答案就会显而易见。",""],[341,15,"unexpected","/ˈʌnikˈspektid/",[["adj","想不到的，意外的"]],[],"","adj.","意外的","The best stories begin with an unexpected turn.","最好的故事，都始于意外的转折。",""],[342,15,"unwilling","/ˈʌnˈwiliŋ/",[["adj","不愿意的"]],[],"","adj.","不愿意的","The sun seemed unwilling to set that evening.","那个傍晚，太阳似乎不愿落下。",""],[343,15,"habitat","/ˈhæbitæt/",[["n","栖息地，产地"]],[],"","n.","栖息地","Every pond is a habitat for a hundred tiny lives.","每一个池塘，都是上百种小生命的栖息地。",""],[344,15,"retire","/riˈtaiə/",[["v","退休"],["n","退休"]],[],"","v.","退休","After he retired, he grew roses and wrote letters.","他退休后，种玫瑰，写信。",""],[345,15,"defend","/diˈfend/",[["v","保卫，辩护"]],[],"","v.","保卫；为…辩护","Defend your ideas with reasons, not volume.","用道理而不是音量，捍卫你的观点。",""],[346,15,"withdraw","/wiðˈdrɔː/",[["v","撤退，撤回；取款"]],[],"","v.","撤回；取（款）","Withdraw from the noise now and then.","时不时从喧嚣里退出来。",""],[347,15,"participate","/pɑːˈtisipeit/",[["v","参加，参与（in）"]],[],"","v.","参加；参与","Participate fully, even in small things.","哪怕是小事，也全情参与。",""],[348,15,"enable","/iˈneibl/",[["v","使能够；使能够，使成为可能"]],[],"","v.","使能够","Reading enables us to travel without leaving home.","阅读，让我们足不出户就能旅行。",""],[349,14,"accompany","/əˈkʌmpəni/",[["v","陪伴；伴随；与…同时发生；（尤指用钢琴）为…伴奏"]],[],"","v.","陪伴；伴随","A good book accompanies you through long nights.","一本好书，陪你度过漫漫长夜。",""],[350,14,"chief","/tʃiːf/",[["adj","主要的，首要的；（用于职位头衔）主管的，首席的"],["n","首领，领导"]],[],"","adj.","主要的；首席的","The chief cause of stress is trying to do everything at once.","压力的主要原因，是想一次做完所有事。",""],[351,14,"explode","/iksˈpləud/",[["v","爆炸；爆发"]],[],"","v.","爆发；爆炸","The garden exploded with color after the rain.","雨后，花园里色彩怒放。",""],[352,14,"precious","/ˈpreʃəs/",[["adj","珍贵的；宝贵的"]],[],"","adj.","珍贵的；宝贵的","Youth fades fast and learning comes slow; every inch of time is precious.","少年易老学难成，一寸光阴不可轻。","朱熹"],[353,14,"register","/ˈredʒistə/",[["v","注册，登记；记录；流露出，显得，表达出"]],[],"","v.","登记；显露出","Relief registered on her face when she saw the score.","看到分数时，她脸上露出了释然。",""],[354,14,"remark","/riˈmaːk/",[["v","评论，说起"],["n","评论，谈论"]],[],"","n.","评论；v. 谈论","A careless remark can stay with someone for years.","一句随口的评论，可能让人记好多年。",""],[355,14,"curiosity","/ˌkjʊəriˈɒsəti/",[["n","好奇心；求知欲"]],[],"","n.","好奇心","Curiosity is the engine of learning.","好奇心，是学习的引擎。",""],[356,14,"theory","/ˈθɪəri/",[["n","理论；学说"]],[],"","n.","理论；学说","In theory, it's easy; in practice, it's practice.","理论上很简单，实践中就是练习。",""],[357,14,"thick","/θɪk/",[["adj","厚的；浓的"]],[],"","adj.","厚的；浓的","The fog was so thick we could only hear the sea.","雾浓得我们只能听见海的声音。",""],[358,14,"affordable","/əˈfɔːdəbl/",[["adj","支付得起的；负担得起的"]],[],"","adj.","负担得起的","Kindness is the most affordable luxury.","善意，是最负担得起的奢侈品。",""],[359,14,"atmosphere","/ˈætməsfiə/",[["n","大气，大气层；氛围"]],[],"","n.","氛围；大气","Libraries have an atmosphere of quiet courage.","图书馆里，有一种安静的勇气的氛围。",""],[360,14,"household","/ˈhaushəuld/",[["n","家庭；家庭成员"]],[],"","n.","家庭；一家人","The whole household woke to the smell of pancakes.","全家人都被松饼的香味唤醒了。",""],[361,14,"humour","/ˈhjuːmə/",[["n","幽默；幽默感"]],["humor"],"美式拼写 humor","n.","幽默","A little humour makes heavy days lighter.","一点幽默，能让沉重的日子轻一些。",""],[362,14,"whisper","/ˈwispə/",[["v","耳语，私语；低声说话"]],[],"","v.","低语；耳语","The leaves whisper when the wind passes.","风吹过时，树叶在低语。",""],[363,14,"wipe","/waip/",[["v","擦，擦拭；消除，抹去"],["n","擦，拭；湿抹布；湿巾"]],[],"","v.","擦去；擦拭","Wipe the slate clean and start again.","把石板擦干净，重新开始。",""],[364,14,"optimistic","/ˌɔptiˈmistik/",[["adj","乐观的；乐观主义的"]],[],"","adj.","乐观的","An optimistic heart sees a garden in every seed.","乐观的心，在每一颗种子里看见花园。",""],[365,14,"significant","/sigˈnifikənt/",[["adj","重要的；显著的；有意义的；意味深远的"]],[],"","adj.","重要的；有意义的","Small daily efforts make a significant difference.","每天的小小努力，会带来显著的不同。",""],[366,14,"region","/ˈriːdʒən/",[["n","地区，范围"]],[],"","n.","地区；区域","Each region of China has its own way of making noodles.","中国的每个地区，都有自己做面条的方式。",""],[367,13,"addiction","/əˈdikʃən/",[["n","上瘾，成瘾（to）"]],[],"","n.","上瘾","Phone addiction steals the hours we never notice.","手机上瘾，偷走了我们没察觉的时间。",""],[368,13,"facility","/fəˈsiliti/",[["n","设施；设备"]],[],"","n.","设施；设备","The new sports facility is open until ten.","新的运动设施开放到晚上十点。",""],[369,13,"recall","/riˈkɔːl/",[["v","回忆，回想起；召回"]],[],"","v.","回想起","This feeling could be recalled as memory; but at the time, I was lost.","此情可待成追忆，只是当时已惘然。","李商隐"],[370,13,"remote","/riˈməut/",[["adj","偏远的；远程的；遥远的"]],[],"","adj.","遥远的；偏远的","In a remote village, the stars are louder.","在偏远的村庄里，星星更响亮。",""],[371,13,"resist","/riˈzist/",[["v","抵制，抵抗"]],[],"","v.","抵抗；忍住","I can't resist the smell of fresh bread.","我抵挡不住新出炉面包的香气。",""],[372,13,"tax","/tæks/",[["n","税；税款"]],[],"","n.","税","In this world nothing can be said to be certain, except death and taxes.","这世上，除了死亡和税收，没有什么是确定的。","富兰克林"],[373,13,"fascinate","/ˈfæsɪneɪt/",[["v","使入迷；吸引"]],[],"","v.","使着迷","The night sky has fascinated people for thousands of years.","夜空让人类着迷了几千年。",""],[374,13,"ambition","/æmˈbiʃən/",[["n","雄心；志向"]],[],"","n.","志向；雄心","An old steed in the stable still has the ambition to run a thousand miles.","老骥伏枥，志在千里。","曹操"],[375,13,"appeal","/əˈpiːl/",[["n","呼吁；吸引力"],["v","吸引，呼吁（to）"]],[],"","n.","吸引力；v. 呼吁","The appeal of rainy days: tea, a book, and no plans.","雨天的魅力：一杯茶，一本书，无事可做。",""],[376,13,"associate","/əˈsəuʃieit/",[["v","联系，关联（with）"]],[],"","v.","联想；联系","I associate the smell of oranges with winter.","一闻到橘子的味道，我就想起冬天。",""],[377,13,"declare","/diˈklɛə/",[["v","声明；宣布"]],[],"","v.","宣布；声明","I declare after all there is no enjoyment like reading!","我敢说，到底什么乐趣也比不上读书！","简·奥斯汀"],[378,13,"minor","/ˈmainə/",[["adj","较小的，次要的，轻微的"],["n","未成年人"]],[],"","adj.","次要的；轻微的","Don't let minor setbacks become major stories.","别让小挫折，变成大故事。",""],[379,13,"severe","/siˈviə/",[["adj","严重的；严厉的"]],[],"","adj.","严重的；严厉的","Without severe cold, how could plum blossoms smell so sweet?","不经一番寒彻骨，怎得梅花扑鼻香。","黄檗禅师"],[380,13,"slip","/slip/",[["v","滑倒，溜走；迅速放置；悄悄塞；偷偷放；（迅速且容易地）穿上，脱下"]],[],"","v.","溜走；悄悄放","Time slips away while we plan to begin.","在我们计划开始的时候，时间就溜走了。",""],[381,12,"academic","/ækəˈdemik/",[["adj","学业的，学术的；教学的；理论的"],["n","高等院校教师；高校科研人员"]],[],"","adj.","学术的；学业的","Academic success is built one ordinary evening at a time.","学业上的成功，是一个个平凡的夜晚堆起来的。",""],[382,12,"pile","/pail/",[["n","堆，大量"]],[],"","n.","一堆；大量","A pile of old letters smells like the past.","一摞旧信，闻起来像过去。",""],[383,12,"pirate","/ˈpaiərit/",[["n","海盗，盗版者"]],[],"","n.","海盗；盗版者","Every child has been a pirate on a sofa ship.","每个孩子都当过沙发船上的海盗。",""],[384,12,"chain","/tʃein/",[["n","链条；一连串，一系列"]],[],"","n.","链子；一连串","A chain is only as strong as its weakest link.","链条的强度，取决于最弱的那一环。","英语谚语"],[385,12,"essential","/iˈsenʃəl/",[["adj","本质的；必要的"]],[],"","adj.","必要的；本质的","What is essential is invisible to the eye.","真正重要的东西，用眼睛是看不见的。","圣埃克苏佩里"],[386,12,"psychology","/saiˈkɔlədʒi/",[["n","心理，心理学"]],[],"","n.","心理学；心理","Psychology tells us that habits are built by repetition.","心理学告诉我们，习惯是重复出来的。",""],[387,12,"reserve","/riˈzəːv/",[["v","预定，保留"],["n","自然保护区；储备（量）；内向，内敛"]],[],"","v.","预订；保留","Reserve judgment until you know the whole story.","在了解全部之前，先保留评判。",""],[388,12,"resort","/riˈzɔːt/",[["n","（度假）胜地"]],[],"","n.","度假胜地","The seaside resort is quiet in winter.","冬天的海滨度假地，格外安静。",""],[389,12,"consist","/kənˈsist/",[["v","由…组成（of/ in）"]],[],"","v.","由…组成","A good day consists of small, kind moments.","美好的一天，由许多小小的善意时刻组成。",""],[390,12,"contest","/ˈkɔntestˌkənˈtest/",[["n","竞赛；争论"],["v","竞赛；争夺"]],[],"","n.","比赛；竞赛","Life is not a contest, but a long walk.","人生不是一场比赛，而是一段长长的散步。",""],[391,12,"command","/kəˈmɑːnd/",[["v","命令，控制"],["n","命令；掌握"]],[],"","v.","命令；n. 掌握","A good command of English opens many doors.","熟练掌握英语，能打开许多扇门。",""],[392,12,"comprehension","/ˌkɒmprɪˈhenʃn/",[["n","理解；理解力"]],[],"","n.","理解；理解力","Reading comprehension grows with every book you finish.","你读完的每一本书，都在提升你的理解力。",""],[393,12,"tough","/tʌf/",[["adj","艰难的，棘手的；坚强的；严厉的，无情的"]],[],"","adj.","坚强的；艰难的","After ten thousand blows it still stands tough, whatever wind may blow.","千磨万击还坚劲，任尔东西南北风。","郑燮"],[394,12,"trend","/trend/",[["n","趋势；潮流"],["v","倾向于"]],[],"","n.","趋势；潮流","Trends come and go; good taste stays.","潮流来来去去，好品味会留下。",""],[395,12,"assignment","/əˈsainmənt/",[["n","分配；任务；作业"]],[],"","n.","作业；任务","Finish the hardest assignment first, while you're fresh.","趁精神好，先完成最难的作业。",""],[396,12,"assistant","/əˈsistənt/",[["n","助手；助理"]],[],"","n.","助手；助理","A notebook is the best assistant a student can have.","笔记本是学生最好的助手。",""],[397,12,"bargain","/ˈbɑːgin/",[["n","便宜货；交易"],["v","讨价还价；协商"]],[],"","n.","便宜货；交易","Time spent reading is always a bargain.","花在阅读上的时间，永远划算。",""],[398,12,"destination","/ˌdestiˈneiʃən/",[["n","目的地；终点"]],[],"","n.","目的地","The journey matters as much as the destination.","旅程和目的地一样重要。",""],[399,11,"adopt","/əˈdɔpt/",[["v","采用，采纳；收养，领养"]],[],"","v.","采纳；收养","Adopt the pace of nature: her secret is patience.","采用大自然的步调吧：她的秘诀是耐心。","爱默生"],[400,11,"cheat","/tʃiːt/",[["n","骗子；作弊行为"],["v","欺骗；作弊"]],[],"","v.","作弊；欺骗","If you cheat on a test, you cheat yourself.","考试作弊，骗的是你自己。",""],[401,11,"cheque","/tʃek/",[["n","支票"]],["check"],"美式拼写 check","n.","支票","Health is a cheque you can't cash later.","健康是一张以后兑现不了的支票。",""],[402,11,"preserve","/priˈzəːv/",[["v","保护，保存，保留"],["n","（某人或群体活动、工作等的）专门领域"]],[],"","v.","保存；保护","Pressed flowers preserve a summer between pages.","压花把一个夏天保存在书页之间。",""],[403,11,"propose","/prəˈpəuz/",[["v","计划，提议，建议，求婚"]],[],"","v.","提议；求婚","I propose we take the long way home.","我提议，我们绕远路回家。",""],[404,11,"manufacture","/ˌmænjuˈfæktʃə/",[["n","制造，生产；制造业"],["v","制造，生产"]],[],"","v.","制造；生产","Factories manufacture goods; schools shape people.","工厂制造商品，学校塑造人。",""],[405,11,"crisis","/ˈkraɪsɪs/",[["n","危机，紧要关头"]],[],"","n.","危机；紧要关头","In Chinese, \"crisis\" holds both danger and opportunity.","中文的“危机”，既有危险，也有机遇。",""],[406,11,"confirm","/kənˈfɜːm/",[["v","确定，证实"]],[],"","v.","确认；证实","The experiment confirmed what she had guessed.","实验证实了她的猜想。",""],[407,11,"foundation","/faunˈdeiʃən/",[["n","基金会，基础，根基"]],[],"","n.","基础；根基","Good habits are the foundation of a good life.","好习惯是美好生活的根基。",""],[408,11,"appropriate","/əˈprəupriət/",[["adj","适当的，恰当的"]],[],"","adj.","恰当的；合适的","Silence is sometimes the most appropriate answer.","沉默，有时是最恰当的回答。",""],[409,11,"approve","/əˈpruːv/",[["v","赞同，同意（of）；批准"]],[],"","v.","赞成；批准","You don't need everyone to approve of your dreams.","你的梦想，不需要每个人都赞成。",""],[410,11,"astronaut","/ˈæstrənɔːt/",[["n","宇航员，太空人"]],[],"","n.","宇航员","Astronauts say Earth looks fragile from space.","宇航员说，从太空看，地球很脆弱。",""],[411,11,"grant","/grɑːnt/",[["v","授予，同意，批准"]],[],"","v.","准予；授予","Never take a sunny day for granted.","永远别把晴天当作理所当然。",""],[412,11,"routine","/ruːˈtiːn/",[["n","例行公事，常规"],["adj","常规的，例行的"]],[],"","n.","日常；惯例","A morning routine is a gift to your future self.","晨间的固定习惯，是送给未来自己的礼物。",""],[413,11,"impractical","/imˈpræktikəl/",[["adj","不切实际的，不实用的"]],[],"","adj.","不切实际的","Some dreams seem impractical until someone does them.","有些梦想看起来不切实际，直到有人做到。",""],[414,11,"distinguish","/diˈstiŋgwiʃ/",[["v","区别，辨别（from）"]],[],"","v.","区分；辨别","Learn to distinguish facts from opinions.","学会区分事实和观点。",""],[415,11,"vital","/ˈvaitl/",[["adj","至关重要的，生死攸关的"]],[],"","adj.","至关重要的","Water is vital to every living thing.","水对每一种生命都至关重要。",""],[416,10,"absence","/ˈæbsns/",[["n","缺乏，缺席"]],[],"","n.","缺席；不在","Absence makes the heart grow fonder.","离别让思念更深。","英语谚语"],[417,10,"peak","/piːk/",[["n","山峰，顶端，顶点"]],[],"","n.","顶峰；山峰","One day I'll stand on the highest peak and see all mountains small below.","会当凌绝顶，一览众山小。","杜甫"],[418,10,"temporary","/ˈtempərəri/",[["adj","暂时的，临时的"]],[],"","adj.","暂时的；临时的","Bad weather is temporary; the sky remains.","坏天气是暂时的，天空一直都在。",""],[419,10,"architect","/ˈɑːkitekt/",[["n","建筑师"]],[],"","n.","建筑师","You are the architect of your own habits.","你是自己习惯的建筑师。",""],[420,10,"universal","/ˌjuːniˈvəːsəl/",[["adj","普遍的，全世界的，通用的"]],[],"","adj.","普遍的；全世界的","Music is a universal language.","音乐是全世界通用的语言。",""],[421,10,"grasp","/grɑːsp/",[["v","抓紧；抓牢；理解；领会"],["n","紧抓，紧握；理解（力）；领会；能力所及"]],[],"","v.","抓住；领会","Grasp the main idea first; the details will follow.","先抓住主旨，细节自然会跟上。",""],[422,10,"decrease","/ˈdiːkriːsˌdiːˈkriːs/",[["v","&"],["n","降低，减少"]],[],"","v.","减少；降低","Fear decreases as understanding grows.","理解越多，恐惧越少。",""],[423,10,"beneficial","/ˌbeniˈfiʃəl/",[["adj","有益的，有利的"]],[],"","adj.","有益的","A short nap is surprisingly beneficial.","小睡一会儿，好处出奇地多。",""],[424,10,"define","/diˈfain/",[["v","定义，明确"]],[],"","v.","定义；明确","Don't let one bad day define you.","别让糟糕的一天定义你。",""],[425,10,"vast","/vɑːst/",[["adj","广阔的，巨大的"]],[],"","adj.","广阔的；巨大的","The sea is vast because it welcomes a hundred rivers.","海纳百川，有容乃大。","林则徐"],[426,10,"witness","/ˈwitnis/",[["v","目击"],["n","目击者，证人"]],[],"","v.","见证；目睹","We witnessed the first snow of the year together.","我们一起见证了今年的第一场雪。",""],[427,10,"wrap","/ræp/",[["v","包裹，覆盖"]],[],"","v.","包裹；覆盖","Fog wrapped the little town like cotton.","雾像棉花一样，裹住了小镇。",""],[428,10,"candidate","/ˈkændidit/",[["n","候选人，应试者"]],[],"","n.","候选人；应试者","Every candidate in the exam hall is braver than they feel.","考场里的每一位考生，都比自己感觉的更勇敢。",""],[429,9,"affair","/əˈfɛə/",[["n","公共事务，政治事务；事件，事情；风流韵事"]],[],"","n.","事务；事情","There is a tide in the affairs of men which, taken at the flood, leads on to fortune.","人间万事都有涨潮之时，抓住了，便通向好运。","莎士比亚"],[430,9,"acquire","/əˈkwaiə/",[["v","获得，取得；购得"]],[],"","v.","获得；习得","Skills are acquired slowly and lost quickly.","技能习得得慢，丢失得快。",""],[431,9,"certificate","/səˈtifikit/",[["n","证书，证明"]],[],"","n.","证书；证明","A certificate proves you finished; your work proves you learned.","证书证明你完成了，作品证明你学会了。",""],[432,9,"champion","/ˈtʃæmpjən/",[["n","冠军"],["v","支付，拥护"]],[],"","n.","冠军；v. 拥护","Champions are made when no one is watching.","冠军是在无人注视时练成的。",""],[433,9,"estimate","/ˈestimeit/",[["v","估计，估算"]],[],"","v.","估计；估算","We always estimate tasks too short and worries too long.","我们总是把任务估得太短，把担忧想得太长。",""],[434,9,"exhausted","/igˈzɔːstid/",[["adj","精疲力竭的；耗尽的，枯竭的"]],[],"","adj.","精疲力竭的","When you're exhausted, rest, but don't quit.","累坏了就休息，但别放弃。",""],[435,9,"refresh","/riˈfreʃ/",[["v","使恢复精力，使凉爽；刷新"]],[],"","v.","使恢复精力；刷新","Cold water refreshes tired eyes.","冷水能让疲惫的眼睛清醒过来。",""],[436,9,"contract","/ˈkɔntrækt/",[["n","合同"],["v","订合同；收缩；感染（疾病），得（病）"]],[],"","n.","合同；v. 收缩","Metal contracts in the cold.","金属遇冷会收缩。",""],[437,9,"critical","/ˈkrɪtɪkl/",[["adj","批评的；关键的，决定性的；危急的"]],[],"","adj.","关键的；批判的","Critical thinking is asking \"how do you know?\"","批判性思维，就是问一句“你怎么知道？”",""],[438,9,"civil","/ˈsɪvl/",[["adj","国民的，平民的；国家的，政府的（非宗教或军事的）；民事的（非刑事的）；有礼貌的，客气的"]],[],"","adj.","文明的；国民的","Keep the conversation civil, even when you disagree.","即使意见不合，也要文明交谈。",""],[439,9,"compose","/kəmˈpəʊz/",[["v","组成，构成；创作（音乐、文学等）"]],[],"","v.","组成；创作","Forever is composed of nows.","永远，由无数个此刻组成。","艾米莉·狄金森"],[440,9,"splendid","/ˈsplendɪd/",[["adj","极好的，壮丽的"]],[],"","adj.","极好的；壮丽的","From the hilltop, the view was splendid.","从山顶望去，景色壮丽。",""],[441,9,"strike","/straɪk/",[["v","打，击；侵袭，爆发；突然想到，一下子想起，猛地意识到；罢工"],["n","罢工；袭击；（尤指）空袭；击；打"]],[],"","v.","突然想到；打击","An idea struck me in the shower.","洗澡时，我突然冒出一个主意。",""],[442,9,"threaten","/ˈθretn/",[["v","威胁，恐吓"]],[],"","v.","威胁；预示","Dark clouds threaten rain over the hills.","乌云压在山头，眼看要下雨。",""],[443,9,"tragedy","/ˈtrædʒədi/",[["n","悲剧；悲惨事件"]],[],"","n.","悲剧","Life is a tragedy when seen in close-up, but a comedy in long-shot.","人生近看是悲剧，远看是喜剧。","卓别林"],[444,9,"transform","/trænsˈfɔːm/",[["v","转换，变形"]],[],"","v.","改变；转变","A caterpillar transforms without being told how.","毛毛虫蜕变，不需要谁来教。",""],[445,9,"trial","/ˈtraɪəl/",[["n","试验；审讯，审判"]],[],"","n.","试验；审判","Every trial teaches what easy days cannot.","每一次考验，都教会安逸日子教不了的东西。",""],[446,9,"fantasy","/ˈfæntəsi/",[["n","幻想，奇幻"]],[],"","n.","幻想；奇幻","A good fantasy novel is a door in the wall.","一本好的奇幻小说，是墙上的一扇门。",""],[447,9,"fetch","/fetʃ/",[["v","取来，拿来"]],[],"","v.","拿来；取来","The puppy fetched the ball and dropped it at my feet.","小狗把球叼回来，放在我脚边。",""],[448,9,"frequently","/ˈfriːkwəntli/",[["adv","频繁地，经常地"]],[],"","adv.","经常地；频繁地","The words you use frequently shape how you think.","你常用的词，塑造你思考的方式。",""],[449,9,"glance","/glɑːns/",[["v","瞥一眼；匆匆一看；扫视"],["n","一瞥，一看"]],[],"","n.","一瞥；v. 瞥","I glance back, and there she is, where the lantern light is dim.","蓦然回首，那人却在，灯火阑珊处。","辛弃疾"],[450,9,"assume","/əˈsjuːm/",[["v","假设，假定；承担，采取"]],[],"","v.","假设；以为","Never assume; ask.","别想当然，问一问。",""],[451,9,"uncertain","/ʌnˈsəːtn/",[["adj","不确定的；无把握的；难预料的"]],[],"","adj.","不确定的","When the path is uncertain, take one clear step.","路不确定时，先迈出一步清楚的。",""],[452,9,"urban","/ˈəːbən/",[["adj","城市的，都市的"]],[],"","adj.","城市的","Urban gardens grow on rooftops and balconies.","城市里的花园，长在屋顶和阳台上。",""],[453,9,"harbour","/ˈhɑːbə/",[["n","港口"],["v","窝藏，庇护（罪犯等）；怀有，心怀（尤指反面感情或想法）"]],[],"","n.","港湾；v. 怀有","A ship in harbour is safe, but that is not what ships are built for.","船停在港湾里很安全，但造船不是为了这个。","约翰·谢德"],[454,9,"harmony","/ˈhɑːməni/",[["n","和谐；协调"]],[],"","n.","和谐；协调","The highest education … makes our life in harmony with all existence.","最高的教育……让我们的生命与万物和谐共处。","泰戈尔"],[455,9,"identify","/aiˈdentifai/",[["v","识别，鉴定；找到，发现"]],[],"","v.","识别；发现","Identify the problem before you solve it.","先找出问题，再解决它。",""],[456,9,"impact","/ˈimpækt/",[["n","影响；冲击"]],[],"","n.","影响；冲击","One teacher can have an impact for a lifetime.","一位老师的影响，可能持续一生。",""],[457,9,"distinct","/diˈstiŋkt/",[["adj","不同的；明显的，显著的"]],[],"","adj.","明显的；截然不同的","Each season has its own distinct smell.","每个季节，都有它独特的气味。",""],[458,9,"scratch","/skrætʃ/",[["v","抓；搔；划伤"]],[],"","v.","挠；划伤","The cat scratched at the door to be let in.","猫挠着门，想进屋来。",""],[459,9,"burst","/bəːst/",[["v","爆发；爆裂；突然发生；突然出现"]],[],"","v.","突然…；爆裂","The whole class burst into laughter.","全班哄堂大笑。",""],[460,9,"cancel","/ˈkænsl/",[["v","取消，撤销"]],[],"","v.","取消","The rain cancelled the match, so we played chess.","雨取消了比赛，我们就下起了棋。",""],[461,9,"skip","/skip/",[["v","跳过，略过；蹦蹦跳跳地走；悄悄溜走；突然离开"]],[],"","v.","跳过；蹦跳","Don't skip breakfast on exam day.","考试那天，别跳过早餐。",""],[462,8,"pedestrian","/piˈdestriən/",[["n","行人，步行者"]],[],"","n.","行人","Pedestrians stopped to watch the sunset over the bridge.","行人们停下来，看桥上的日落。",""],[463,8,"peer","/piə/",[["n","同辈人，同辈"],["v","凝视，仔细看"]],[],"","v.","凝视；n. 同龄人","Peer pressure can push you up as well as down.","同伴压力，既能把你往下拽，也能把你往上推。",""],[464,8,"casual","/ˈkæʒjuəl/",[["adj","漫不经心的，不在乎的；非正式的，随便的；偶然的，碰巧的；感情不深的，疏远的"]],[],"","adj.","随意的；非正式的","A casual walk can turn into a long talk.","一次随意的散步，可能变成一场长谈。",""],[465,8,"erupt","/iˈrʌpt/",[["v","喷发；爆发"]],[],"","v.","喷发；爆发","Applause erupted when the last note faded.","最后一个音符消散时，掌声爆发了。",""],[466,8,"principle","/ˈprinsəpl/",[["n","原则，原理"]],[],"","n.","原则；原理","Stick to your principles, even when it's hard.","即使艰难，也要坚持原则。",""],[467,8,"loose","/luːs/",[["adj","宽松的，松散的；疏松的；不结实的，不坚固的；不严谨的，不严密的"]],[],"","adj.","松散的；宽松的","A loose thread can unravel a whole sweater.","一根松掉的线，能拆散一整件毛衣。",""],[468,8,"correspond","/ˌkɔrisˈpɔnd/",[["v","（与…）通信；类似于，相当于；相一致，符合"]],[],"","v.","通信；相一致","Your actions should correspond to your words.","行动应当与言语一致。",""],[469,8,"advocate","/ˈædvəkeɪt/",[["v","提倡，支持"],["n","支持者，提倡者"]],[],"","v.","提倡；拥护","Doctors advocate eight hours of sleep.","医生提倡睡足八小时。",""],[470,8,"ashamed","/əˈʃeimd/",[["adj","感到羞耻的，感到惭愧的（of）"]],[],"","adj.","惭愧的","Never be ashamed of asking a question.","永远别因为提问而感到羞愧。",""],[471,8,"automatic","/ˌɔːtəˈmætik/",[["adj","自动的；无意识的"]],[],"","adj.","自动的；无意识的","After enough practice, good habits become automatic.","练习得足够多，好习惯就会变成本能。",""],[472,8,"decorate","/ˈdekəreit/",[["v","装饰，布置"]],[],"","v.","装饰；布置","We decorated the classroom with paper cranes.","我们用纸鹤布置教室。",""],[473,8,"rough","/rʌf/",[["adj","粗糙的，不平滑的；不确切的，粗略的，大致的；粗暴的，粗野的，猛烈的"]],[],"","adj.","粗糙的；艰难的","A rough draft is better than a perfect blank page.","粗糙的草稿，好过完美的空白页。",""],[474,8,"honorable","/ˈɔnərəbl/",[["adj","可敬的，值得钦佩的；品德高尚的，体面的"]],[],"","adj.","可敬的；高尚的","Losing honorably is better than winning unfairly.","体面地输，好过不公平地赢。",""],[475,8,"illegal","/iˈliːgəl/",[["adj","非法的，违法的"]],[],"","adj.","非法的","Picking flowers in the national park is illegal.","在国家公园里摘花是违法的。",""],[476,8,"negotiate","/niˈgəuʃieit/",[["v","协商，谈判"]],[],"","v.","协商；谈判","The best negotiators listen more than they talk.","最好的谈判者，听得比说得多。",""],[477,8,"vivid","/ˈvivid/",[["adj","生动的，清晰的，逼真的；鲜明的，耀眼的，鲜艳的"]],[],"","adj.","生动的；鲜艳的","Frost-touched maple leaves are more vivid than February flowers.","霜叶红于二月花。","杜牧"],[478,8,"scan","/skæn/",[["v","细看，察看，审视，端详；粗略地读，浏览，翻阅；（用扫描设备）扫描（图像或文件）"]],[],"","v.","扫视；浏览","Scan the questions first, then begin.","先浏览一遍题目，再开始作答。",""],[479,8,"sculpture","/ˈskʌlptʃə/",[["n","雕塑，雕像"]],[],"","n.","雕塑","Every block of stone has a sculpture inside it.","每一块石头里，都藏着一尊雕像。",""],[480,8,"selfish","/ˈselfiʃ/",[["adj","自私的，利己的"]],[],"","adj.","自私的","Taking care of yourself is not selfish.","照顾好自己，并不自私。",""],[481,8,"burden","/ˈbəːdn/",[["n","负担"],["v","使...负重，使......担忧"]],[],"","n.","负担","When Heaven is about to give someone a great task, it first tests their heart with burden.","天将降大任于是人也，必先苦其心志。","孟子"],[482,7,"absolute","/ˈæbsəluːt/",[["adj","绝对的，完全的"]],[],"","adj.","绝对的；完全的","The night was in absolute silence.","夜里一片绝对的寂静。",""],[483,7,"accomplish","/əˈkɔmpliʃ/",[["v","实现，完成，达到"]],[],"","v.","完成；实现","Small daily steps accomplish great things.","每天的小步子，能成就大事。",""],[484,7,"accuse","/əˈkjuːz/",[["v","控告；指控；指责"]],[],"","v.","指责；控告","Don't accuse the clock; start now.","别怪时钟，现在就开始。",""],[485,7,"administration","/ədˌminiˈstreiʃən/",[["n","管理，行政；政府，行政机关"]],[],"","n.","管理；行政部门","The school administration planted trees along the track.","学校管理处在跑道边种了树。",""],[486,7,"perception","/pəˈsepʃən/",[["n","认识，观念，看法；感知；洞察力，理解能力"]],[],"","n.","认识；感知","Travel changes our perception of home.","旅行改变我们对家的认识。",""],[487,7,"radiation","/ˌreidiˈeiʃən/",[["n","辐射，放射；辐射物"]],[],"","n.","辐射","Sunscreen protects skin from harmful radiation.","防晒霜保护皮肤，免受有害辐射。",""],[488,7,"reject","/riˈdʒekt/",[["v","拒绝，驳回；排斥"]],[],"","v.","拒绝；排斥","Every famous writer was rejected many times.","每个著名作家，都被拒绝过很多次。",""],[489,7,"mild","/maild/",[["adj","轻微的，温和的；和缓的"]],[],"","adj.","温和的；轻微的","A mild winter brought early blossoms.","暖冬让花开得早了。",""],[490,7,"symptom","/ˈsɪmptəm/",[["n","症状；征兆"]],[],"","n.","症状；征兆","Yawning is a symptom of boredom, or of a late night.","打哈欠，是无聊的症状，或者熬夜了。",""],[491,7,"treasure","/ˈtreʒə(r)/",[["n","财富，宝藏"],["v","珍藏，珍惜，珍视"]],[],"","n.","宝藏；v. 珍惜","Treasure the friends who tell you the truth.","珍惜那些对你说真话的朋友。",""],[492,7,"tuition","/tjuˈɪʃn/",[["n","学费；（尤指对小组的）教学，讲课"]],[],"","n.","学费；教学","Experience charges high tuition, but its lessons last.","经验收取高昂的学费，但它的课程终身受用。",""],[493,7,"foster","/ˈfɔstə/",[["v","培养，促进，助长；鼓励；寄养，代养"],["adj","收养的"]],[],"","v.","培养；促进","Good teachers foster curiosity, not fear.","好老师培养好奇心，而不是恐惧。",""],[494,7,"freezing","/ˈfriːziŋ/",[["adj","冰冻的，极冷的"]],[],"","adj.","极冷的；冰冻的","On freezing mornings, the windows bloom with frost.","在严寒的早晨，窗上开满了霜花。",""],[495,7,"annual","/ˈænjuəl/",[["adj","每年的，年度的"]],[],"","adj.","每年的；年度的","The annual flower festival fills the town with color.","一年一度的花节，让小镇缤纷起来。",""],[496,7,"antique","/ænˈtiːk/",[["adj","古老的，古董的"],["n","古董，古物"]],[],"","adj.","古董的；古老的","An antique clock still keeps perfect time.","一座古董钟，依然走得分秒不差。",""],[497,7,"arise","/əˈraiz/",[["v","出现，发生；起床；起立；起身"]],[],"","v.","出现；产生","Walk to where the stream ends, sit, and watch the clouds arise.","行到水穷处，坐看云起时。","王维"],[498,7,"unemployment","/ˈʌnimˈplɔimənt/",[["n","失业；失业人数"]],[],"","n.","失业","Unemployment can be a pause, not an ending.","失业可以是一次停顿，而不是结局。",""],[499,7,"gravity","/ˈgræviti/",[["n","重力，地心引力；（局势的）严重性"]],[],"","n.","重力；严重性","Gravity keeps our feet on the ground; dreams lift our eyes.","重力让我们脚踏实地，梦想让我们抬头仰望。",""],[500,7,"rural","/ˈruːrəl/",[["adj","农村的，乡村的"]],[],"","adj.","乡村的；农村的","Rural nights are full of frogs and stars.","乡村的夜晚，满是蛙声和星光。",""],[501,7,"scare","/skɛə/",[["v","使惊吓，吓唬"]],[],"","v.","吓唬；使惊吓","New things scare us until they become familiar.","新事物总会吓到我们，直到它变得熟悉。",""],[502,7,"murder","/ˈməːdə/",[["n","谋杀，凶杀"],["v","谋杀，杀害"]],[],"","n.","谋杀","Agatha Christie wrote murder mysteries in her bath.","阿加莎·克里斯蒂爱在浴缸里写谋杀推理小说。",""],[503,7,"horizon","/həˈraizn/",[["n","地平线；（pl.）（欲望、知识或兴趣的）范围，眼界"]],[],"","n.","地平线；眼界","Books expand our horizons.","书籍开阔我们的眼界。",""],[504,7,"noble","/ˈnəubl/",[["adj","高贵的，贵族的"]],[],"","adj.","高尚的；高贵的","Forgiveness is a noble kind of strength.","原谅，是一种高贵的力量。",""],[505,7,"desperate","/ˈdespərit/",[["adj","绝望的；不顾一切的，孤注一掷的"]],[],"","adj.","绝望的；极度渴望的","Desperate times call for creative ideas.","非常时期，需要有创意的办法。",""],[506,7,"weaken","/ˈwiːkən/",[["v","使变弱，削弱；减弱"]],[],"","v.","减弱；削弱","Excuses weaken the will.","借口会削弱意志。",""],[507,7,"seize","/siːz/",[["v","抓住，夺取；强占，占领"]],[],"","v.","抓住；夺取","Seize the moment; the years wait for no one.","及时当勉励，岁月不待人。","陶渊明"],[508,6,"acknowledge","/əkˈnɔlidʒ/",[["v","承认；认可；感谢"]],[],"","v.","承认；认可","To acknowledge what you know and what you don't — that is knowledge.","知之为知之，不知为不知，是知也。","孔子"],[509,6,"payment","/ˈpeimənt/",[["n","支付，付款；报酬，偿还"]],[],"","n.","报酬；付款","Gratitude is a payment that costs nothing.","感激，是一种不花钱的报酬。",""],[510,6,"priority","/praiˈɔriti/",[["n","优先权，优先顺序；重要性"]],[],"","n.","优先；重点","Make sleep a priority, not a reward.","把睡眠当作优先事项，而不是奖励。",""],[511,6,"procedure","/prəˈsiːdʒə/",[["n","程序，步骤"]],[],"","n.","程序；步骤","Follow the procedure, but keep your eyes open.","按步骤来，但要保持警觉。",""],[512,6,"quote","/kwəut/",[["n","引用"],["v","引述，引用；举例说明"]],[],"","v.","引用；n. 引语","She quoted a poem that made the room go quiet.","她引用了一首诗，整个房间都安静下来。",""],[513,6,"luxury","/ˈlʌkʃəri/",[["n","豪华，奢侈"]],[],"","n.","奢侈；奢华","An unhurried breakfast is a small luxury.","不慌不忙地吃顿早餐，是一种小小的奢侈。",""],[514,6,"contemporary","/kənˈtempərəri/",[["adj","当代的，现在的"]],[],"","adj.","当代的","Contemporary art asks questions rather than answers them.","当代艺术提出问题，而不是回答问题。",""],[515,6,"cooperate","/kəuˈɔpəreit/",[["v","合作，协作"]],[],"","v.","合作；协作","Ants cooperate to carry what no single ant can.","蚂蚁们合作，搬动单只蚂蚁搬不动的东西。",""],[516,6,"classify","/ˈklæsɪfaɪ/",[["v","分类，归类"]],[],"","v.","分类；归类","Scientists classify living things into groups.","科学家把生物分门别类。",""],[517,6,"tight","/taɪt/",[["adj","紧的，紧密的；（控制）严格的，严密的"],["adv","紧紧地，牢牢地"]],[],"","adj.","紧的；adv. 紧紧地","Hold on tight; the best part of the ride is coming.","抓紧了，最精彩的部分要来了。",""],[518,6,"tropical","/ˈtrɒpɪkl/",[["adj","热带的"]],[],"","adj.","热带的","Tropical rainforests are the lungs of the earth.","热带雨林是地球之肺。",""],[519,6,"fierce","/fiəs/",[["adj","激烈的，猛烈的，凶猛的"]],[],"","adj.","凶猛的；激烈的","Though she be but little, she is fierce.","她虽然个子小，却很凶猛。","莎士比亚"],[520,6,"flexible","/ˈfleksəbl/",[["adj","灵活的，可弯曲的，适应性强的"]],[],"","adj.","灵活的；可弯曲的","Bamboo is flexible, so the storm cannot break it.","竹子柔韧，所以风暴折不断它。",""],[521,6,"fortunate","/ˈfɔːtʃənit/",[["adj","幸运的"]],[],"","adj.","幸运的","We are fortunate to live in a time of so many books.","我们有幸生活在一个书籍丰富的时代。",""],[522,6,"giant","/ˈdʒaiənt/",[["adj","巨大的"],["n","行业巨头，大公司；巨人，巨兽；伟人，卓越人物"]],[],"","adj.","巨大的；n. 巨人","A giant moon rose over the quiet sea.","一轮巨大的月亮，从静静的海面升起。",""],[523,6,"aggressive","/əˈgresiv/",[["adj","好斗的；积极的，有进取心的"]],[],"","adj.","好斗的；积极进取的","Be gentle with people and aggressive with goals.","对人温柔，对目标积极进取。",""],[524,6,"anniversary","/ˌæniˈvəːsəri/",[["n","周年纪念日"]],[],"","n.","周年纪念日","On their 50th anniversary, they planted another tree.","结婚五十周年时，他们又种了一棵树。",""],[525,6,"undoubtedly","/ʌnˈdautidli/",[["adv","无疑地，确信地"]],[],"","adv.","毫无疑问地","Undoubtedly, the best time to start is now.","毫无疑问，最好的开始时间就是现在。",""],[526,6,"deed","/diːd/",[["n","行为；事迹，功绩"]],[],"","n.","行为；事迹","A good deed is never wasted.","一件善举，永远不会白费。",""],[527,6,"barely","/ˈbɛəli/",[["adv","几乎不；勉强才能够；仅仅"]],[],"","adv.","几乎不；勉强","We barely caught the last train, laughing all the way.","我们勉强赶上末班车，一路都在笑。",""],[528,6,"rival","/ˈraivəl/",[["n","对手，竞争者"],["v","与...竞争，匹敌"]],[],"","n.","对手；v. 匹敌","A good rival makes you better.","一个好对手，会让你变得更好。",""],[529,6,"salary","/ˈsæləri/",[["n","薪水，工资"]],[],"","n.","薪水；工资","No salary can pay for a love of your work.","多少薪水，也买不来对工作的热爱。",""],[530,6,"hurricane","/ˈhʌrikən/",[["n","飓风"]],[],"","n.","飓风","The eye of a hurricane is strangely calm.","飓风的风眼里，出奇地平静。",""],[531,6,"demonstrate","/ˈdemənstreit/",[["v","证明；演示；示威"]],[],"","v.","证明；演示","The teacher demonstrated the experiment slowly.","老师慢慢地演示了这个实验。",""],[532,6,"beneath","/biˈniːθ/",[["prep","在…之下"]],[],"","prep.","在…之下","Beneath the snow, the seeds are dreaming of spring.","在雪下面，种子正梦见春天。",""],[533,6,"brilliant","/ˈbriljənt/",[["adj","（光线）明亮的；（色彩）艳丽的；绝顶聪明的，才华横溢的；卓越的，杰出的"]],[],"","adj.","灿烂的；聪明的","Brilliant ideas often begin as silly questions.","绝妙的点子，往往始于傻乎乎的问题。",""],[534,6,"shortcoming","/ʃɔːtˌkʌmiŋ/",[["n","缺点，不足"]],[],"","n.","缺点；不足","Knowing your shortcomings is the first step to growth.","认识自己的不足，是成长的第一步。",""],[535,6,"optional","/ˈɔpʃənl/",[["adj","可选择的，非强制的"]],[],"","adj.","可选的；非强制的","Kindness is never optional.","善良，从来不是可选项。",""],[536,6,"paradise","/ˈpærədais/",[["n","天堂，乐园"]],[],"","n.","天堂；乐园","I have always imagined that Paradise will be a kind of library.","我总是想象，天堂应该是图书馆的模样。","博尔赫斯"],[537,6,"emphasis","/ˈemfəsis/",[["n","强调（on），重点"]],[],"","n.","强调；重点","Put the emphasis on progress, not perfection.","把重点放在进步上，而不是完美上。",""],[538,6,"calculate","/ˈkælkjuleit/",[["v","计算，估算"]],[],"","v.","计算","You can't calculate the value of a good friend.","好朋友的价值，是算不出来的。",""],[539,5,"permanent","/ˈpəːmənənt/",[["adj","永久的；持久地"]],[],"","adj.","永久的；持久的","If love is permanent, why must we be together every morning and night?","两情若是久长时，又岂在朝朝暮暮。","秦观"],[540,5,"capture","/ˈkæptʃə/",[["v","捕获；占领；捕捉（影像或声音）"]],[],"","v.","捕捉；捕获","A photo captures a moment; a poem captures a feeling.","照片捕捉瞬间，诗捕捉感受。",""],[541,5,"justice","/ˈdʒʌstis/",[["n","正义"]],[],"","n.","正义；公平","Justice delayed is justice denied.","迟到的正义，就是被剥夺的正义。","英语法谚"],[542,5,"keen","/kiːn/",[["adj","热衷的，渴望的；敏锐的"]],[],"","adj.","热衷的；敏锐的","A keen eye notices the first leaf of autumn.","敏锐的眼睛，能发现秋天的第一片落叶。",""],[543,5,"pure","/pjʊər/",[["adj","纯净的，纯洁的"]],[],"","adj.","纯净的；纯洁的","Mountain air is pure and cold.","山里的空气纯净而清冷。",""],[544,5,"pursue","/pəˈsjuː/",[["v","追求，追赶"]],[],"","v.","追求；追赶","The road ahead is long and far; high and low I will pursue my search.","路漫漫其修远兮，吾将上下而求索。","屈原"],[545,5,"reform","/riˈfɔːrm/",[["v","改革"],["n","改革"]],[],"","v.","改革；n. 改革","Every reform begins with someone saying \"why not?\"","每一次改革，都始于有人问“为什么不呢？”",""],[546,5,"legend","/ˈledʒənd/",[["n","传奇，传说"]],[],"","n.","传奇；传说","Every legend was once an ordinary person who didn't give up.","每个传奇，都曾是一个没有放弃的普通人。",""],[547,5,"clarify","/ˈklærəfaɪ/",[["v","阐明，澄清"]],[],"","v.","阐明；澄清","Writing things down clarifies your thinking.","写下来，能让你的思路变清晰。",""],[548,5,"subordinate","/səˈbɔːdɪnət/",[["adj","从属的，次要的"],["v","使从属于"],["n","部下，下级"]],[],"","adj.","次要的；从属的","Let worry be subordinate to action.","让担忧服从于行动。",""],[549,5,"swallow","/ˈswɒləʊ/",[["v","吞下"],["n","燕子；吞，咽"]],[],"","v.","吞下；n. 燕子","One swallow does not make a summer.","一燕不成夏。","英语谚语"],[550,5,"transfer","/trænsˈfɜː(r)/",[["v","&"],["n","搬运，迁移；转移（地方）；调动（工作）；转乘"]],[],"","v.","转移；转乘","We transferred at a tiny station full of flowers.","我们在一个开满鲜花的小站换乘。",""],[551,5,"trigger","/ˈtrɪɡə(r)/",[["v","启动；使爆炸；引发，激发，触发"],["n","（枪的）扳机"]],[],"","v.","引发；触发","A single smell can trigger a childhood memory.","一种气味，就能唤起一段童年的回忆。",""],[552,5,"fasten","/ˈfæsn/",[["v","扣牢，系牢，缚紧，把（拉链）拉好；使牢固，使固定；握住；抓牢；咬住"]],[],"","v.","系牢；扣紧","Fasten your seatbelt; the adventure begins.","系好安全带，冒险开始了。",""],[553,5,"fulfill","/fulˈfil/",[["v","履行，实现；使有成就感，使满足"]],[],"","v.","实现；履行","Fulfill one small promise to yourself each day.","每天兑现一个对自己的小承诺。",""],[554,5,"arrest","/əˈrest/",[["v","逮捕，拘留"],["n","逮捕，拘捕；停止，中止"]],[],"","v.","吸引（注意）；逮捕","A bright red kite arrested everyone's attention.","一只鲜红的风筝，吸引了所有人的目光。",""],[555,5,"unbelievable","/ˌʌnbiˈliːvəbl/",[["adj","难以置信的"]],[],"","adj.","难以置信的","The view from the top was simply unbelievable.","山顶的景色，简直令人难以置信。",""],[556,5,"unconscious","/ʌnˈkɔnʃəs/",[["adj","无知觉（意识）的，昏迷的"]],[],"","adj.","无意识的；昏迷的","Many of our choices are unconscious habits.","我们的许多选择，其实是无意识的习惯。",""],[557,5,"unforgettable","/ˈʌnfəˈgetəbl/",[["adj","难忘的"]],[],"","adj.","难忘的","The most unforgettable trips are often unplanned.","最难忘的旅行，往往是没计划的。",""],[558,5,"valid","/ˈvælid/",[["adj","有效的"]],[],"","adj.","有效的；合理的","Your feelings are valid, even when they're messy.","你的感受是合理的，哪怕它们乱糟糟的。",""],[559,5,"deadline","/ˈdedlain/",[["n","截止时间，最后期限"]],[],"","n.","截止时间；最后期限","A deadline turns \"someday\" into \"today\".","截止日期把“总有一天”变成“就是今天”。",""],[560,5,"restore","/riˈstɔː/",[["v","修复，恢复，复原"]],[],"","v.","恢复；修复","A long walk can restore a tired mind.","一次长长的散步，能让疲惫的头脑复原。",""],[561,5,"reveal","/riˈviːl/",[["v","透露，揭露"]],[],"","v.","揭示；透露","Low tide reveals the secrets of the beach.","退潮时，海滩露出了它的秘密。",""],[562,5,"immigrant","/ˈimigrənt/",[["n","移民"]],[],"","n.","移民","The immigrant grandmother taught us songs from home.","移民来的祖母，教我们唱故乡的歌。",""],[563,5,"opponent","/əˈpəunənt/",[["n","对手，反对者"]],[],"","n.","对手；反对者","Respect your opponent; they make you stronger.","尊重你的对手，是他们让你变强。",""],[564,5,"shrink","/ʃriŋk/",[["v","收缩，缩小"]],[],"","v.","收缩；缩小","Problems shrink when you face them.","直面问题时，问题就变小了。",""],[565,5,"skeptical","/ˈskeptikəl/",[["adj","感到怀疑的"]],[],"","adj.","怀疑的","Be skeptical of anything that sounds too easy.","对听起来太容易的事，保持怀疑。",""],[566,4,"abstract","/æbˈstrækt/",[["adj","抽象的"],["n","（演讲、文章等的）摘要，概要"],["v","抽取，提取；使分离"]],[],"","adj.","抽象的；n. 摘要","Math makes abstract ideas beautifully exact.","数学让抽象的概念变得优美而精确。",""],[567,4,"abuse","/əˈbjuːz/",[["v","滥用；虐待；辱骂"],["n","滥用；虐待；辱骂"]],[],"","v.","滥用；n. 滥用","Don't abuse your body with late nights.","别用熬夜糟蹋身体。",""],[568,4,"accumulate","/əˈkjuːmjuleit/",[["v","积累"]],[],"","v.","积累","Without accumulating small steps, you cannot travel a thousand miles.","不积跬步，无以至千里。","荀子"],[569,4,"accustom","/əˈkʌstəm/",[["v","使习惯（to）"]],[],"","v.","使习惯","Our eyes soon accustom themselves to the dark.","我们的眼睛很快就会习惯黑暗。",""],[570,4,"pesticide","/ˈpestisaid/",[["n","杀虫剂"]],[],"","n.","杀虫剂","Ladybugs are nature's gentle pesticide.","瓢虫是大自然温柔的杀虫剂。",""],[571,4,"capability","/ˌkeipəˈbiliti/",[["n","能力"]],[],"","n.","能力","Your capability grows each time you try something hard.","每次尝试难事，你的能力都在增长。",""],[572,4,"cater","/ˈkeitə/",[["v","（+for/to）为…提供服务，满足…的需要；接待；将…考虑进去，考虑到"]],[],"","v.","迎合；满足需要","This little café caters to students and cats.","这家小咖啡馆，专为学生和猫咪服务。",""],[573,4,"fancy","/ˈfænsi/",[["v","想象，喜欢"],["n","想象的事物；想象（力）；想要，爱好"]],[],"","v.","想要；想象","Do you fancy a walk by the river?","想去河边走走吗？",""],[574,4,"polish","/ˈpɔliʃ/",[["n","擦光剂；上光剂；亮光剂"],["v","擦光，磨光抛光；润色，修改"]],[],"","v.","润色；擦亮","Polish your essay, but don't lose its heart.","润色你的文章，但别丢了它的灵魂。",""],[575,4,"portable","/ˈpɔːtəbl/",[["adj","手提式的"]],[],"","adj.","便携的；手提式的","A book is the most portable kind of magic.","书是最便于携带的魔法。",""],[576,4,"protest","/ˈprəutest/",[["v","抗议（against）"]],[],"","v.","抗议","The lady doth protest too much, methinks.","我看那位夫人表白得太过了。","莎士比亚"],[577,4,"stimulus","/ˈstɪmjələs/",[["n","刺激；刺激物"]],[],"","n.","刺激；刺激物","Curiosity needs a stimulus: a question, a story, a mystery.","好奇心需要一点刺激：一个问题、一个故事、一个谜。",""],[578,4,"summarize","/ˈsʌməraɪz/",[["v","概括，总结"]],["summarise"],"英式拼写 summarise","v.","概括；总结","Can you summarize your day in three words?","你能用三个词，总结你的一天吗？",""],[579,4,"superior","/suːˈpɪəriə(r)/",[["adj","（在品质上）更好的，占优势的，更胜一筹的；（在级别、重要性或职位上）更高的"],["n","级别（或地位、职位）更高的人，上级，上司"]],[],"","adj.","更好的；n. 上级","I say autumn days are superior to spring mornings.","我言秋日胜春朝。","刘禹锡"],[580,4,"surgery","/ˈsɜːdʒəri/",[["n","外科手术"]],[],"","n.","外科手术","After surgery, patience is the best medicine.","手术之后，耐心是最好的药。",""],[581,4,"thoroughly","/ˈθʌrəli/",[["adv","彻底地；极其"]],[],"","adv.","彻底地；极其","To know a thing thoroughly, you must do it yourself.","绝知此事要躬行。","陆游"],[582,4,"trail","/treɪl/",[["n","小径；痕迹"]],[],"","n.","小径；痕迹","A snail leaves a silver trail across the leaf.","蜗牛在叶子上留下一道银色的痕迹。",""],[583,4,"tremble","/ˈtrembl/",[["v","&"],["n","（因紧张、激动、惊慌等）颤抖，哆嗦，抖动，战栗"]],[],"","v.","颤抖；n. 颤动","The candle flame trembled in the breeze.","烛焰在微风中轻轻颤动。",""],[584,4,"format","/ˈfɔːmæt/",[["n","版式，格式，形式"],["v","格式化（磁盘）"]],[],"","n.","格式；形式","The format of the exam has changed, but the words haven't.","考试的形式变了，单词没变。",""],[585,4,"fundamental","/ˌfʌndəˈmentl/",[["adj","十分重大的，根本的"],["n","基本原则"]],[],"","adj.","根本的；基础的","Kindness is fundamental, not optional.","善良是根本，不是可选项。",""],[586,4,"anonymous","/əˈnɔniməs/",[["adj","匿名的"]],[],"","adj.","匿名的","An anonymous note said, \"You're doing great.\"","一张匿名纸条上写着：“你做得很好。”",""],[587,4,"appetite","/ˈæpitait/",[["n","食欲，胃口；强烈欲望，渴望"]],[],"","n.","食欲；渴望","Reading gives you an appetite for more reading.","阅读会让你更想阅读。",""],[588,4,"arouse","/əˈrauz/",[["v","激起，引起（感情、态度）"]],[],"","v.","激起；唤起","The smell of rain aroused memories of summer camp.","雨的气味，唤起了夏令营的回忆。",""],[589,4,"awful","/ˈɔːful/",[["adj","很坏的，极讨厌的，糟糕的；非常的很多的"]],[],"","adj.","糟糕的；可怕的","The weather was awful, but the company was perfect.","天气糟透了，但同伴好极了。",""],[590,4,"vain","/vein/",[["adj","徒劳的（in ~ 徒劳无功）"]],[],"","adj.","徒劳的","If you don't work hard while young, you will grieve in vain when old.","少壮不努力，老大徒伤悲。","《长歌行》"],[591,4,"restless","/ˈrestlis/",[["adj","坐立不安的，不耐烦的；坐立不安的，不安宁的；难以入睡的，辗转反侧的"]],[],"","adj.","焦躁不安的","On restless nights, count your blessings, not sheep.","睡不着的夜晚，数数你的幸运，而不是绵羊。",""],[592,4,"reverse","/riˈvəːs/",[["v","颠倒，反转"],["adj","相反的"],["n","相反的情况（或事物）；背面，反面"]],[],"","v.","颠倒；反转","If you could reverse one day, which would it be?","如果能让一天重来，你会选哪一天？",""],[593,4,"moderate","/ˈmɔdəreit/",[["adj","适度的，中等的；温和的，不激烈的"]],[],"","adj.","适度的；温和的","Moderate exercise is better than none.","适度的运动，总比不动好。",""],[594,4,"offence","/əˈfens/",[["n","冒犯；犯罪"]],["offense"],"美式拼写 offense","n.","冒犯；犯罪","No offence, but your handwriting looks like a spider's dance.","没有冒犯的意思，但你的字像蜘蛛在跳舞。",""],[595,4,"delicate","/ˈdelikit/",[["adj","易碎的；精细的，精美的；纤弱的"]],[],"","adj.","精致的；易碎的","The spider's web is delicate but strong.","蜘蛛网纤细，却很结实。",""],[596,4,"wag","/wæg/",[["v","（狗）摇摆（尾巴）"],["n","摇摆"]],[],"","v.","摇（尾巴）","The dog wagged its tail at the sound of the key.","一听到钥匙声，小狗就摇起了尾巴。",""],[597,4,"breakthrough","/ˈbreɪkθruː/",[["n","重大进展；突破"],["adj","突破性的"]],[],"","n.","突破；重大进展","Every breakthrough looks sudden from the outside.","从外面看，每一次突破都像是突然发生的。",""],[598,4,"reluctant","/riˈlʌktənt/",[["adj","不情愿的，勉强的"]],[],"","adj.","不情愿的","The reluctant reader became the library's best friend.","那个不情愿读书的孩子，后来成了图书馆的好朋友。",""],[599,3,"accent","/ˈæksənt/",[["n","口音；重音"]],[],"","n.","口音；重音","I left home young and returned old; my accent unchanged, my hair grown thin.","少小离家老大回，乡音无改鬓毛衰。","贺知章"],[600,3,"adequate","/ˈædikwit/",[["adj","足够的；合格的；合乎需要的"]],[],"","adj.","足够的；合格的","Adequate sleep is the secret study tool.","充足的睡眠，是秘密的学习工具。",""],[601,3,"pavement","/ˈpeivmənt/",[["n","人行道；石板铺的地面"]],[],"","n.","人行道","Children drew rainbows on the pavement with chalk.","孩子们用粉笔在人行道上画彩虹。",""],[602,3,"prejudice","/ˈpredʒudis/",[["n","偏见；成见"]],[],"","n.","偏见；成见","Prejudice is a cloud that hides the sun.","偏见是遮住太阳的乌云。",""],[603,3,"prosperity","/prɔsˈperiti/",[["n","繁荣，兴旺"]],[],"","n.","繁荣；兴旺","Peace brings prosperity, like rain brings green.","和平带来繁荣，就像雨水带来绿意。",""],[604,3,"resemble","/riˈzembl/",[["v","与…相似"]],[],"","v.","与…相似","Clouds often resemble animals if you look long enough.","看久了，云常常像小动物。",""],[605,3,"resolution","/ˌrezəˈluːʃən/",[["n","解决；解决方案；决心，决定；清晰度，分辨率"]],[],"","n.","决心；解决；分辨率","Make one resolution and keep it.","立下一个决心，并坚持到底。",""],[606,3,"mature","/məˈtjuə/",[["adj","成熟的发酵成熟的，已酿成的"],["v","变成熟；（使）酿成；（使）酿熟"]],[],"","adj.","成熟的；v. 变成熟","Mature people can disagree kindly.","成熟的人，能温和地表达不同意见。",""],[607,3,"latter","/ˈlætə/",[["adj","后者的"]],[],"","adj.","后者的","Between fame and peace, I'd choose the latter.","在名气和安宁之间，我选择后者。",""],[608,3,"lean","/liːn/",[["v","倚，倾斜"],["adj","苗条的，瘦而健美的"]],[],"","v.","倚靠；倾斜","Sunflowers lean toward the light.","向日葵朝着光倾斜。",""],[609,3,"compound","/ˈkɒmpaʊnd/",[["n","化合物；复合物"]],[],"","n.","化合物；复合物","Water is a compound of hydrogen and oxygen.","水是由氢和氧组成的化合物。",""],[610,3,"tolerate","/ˈtɒləreɪt/",[["v","容忍，忍受"]],[],"","v.","容忍；忍受","Cacti tolerate heat that would kill most plants.","仙人掌能忍受让大多数植物死去的高温。",""],[611,3,"transmission","/trænsˈmɪʃn/",[["n","传输；传播"]],[],"","n.","传输；传播","The transmission of knowledge is a kind of relay race.","知识的传递，是一场接力赛。",""],[612,3,"approximately","/əˈprɔksimitli/",[["adv","大约地，近似地"]],[],"","adv.","大约地","The light from the sun takes approximately eight minutes to reach us.","太阳光大约需要八分钟才能抵达我们。",""],[613,3,"artificial","/ˌɑːtiˈfiʃəl/",[["adj","人造的，人工的"]],[],"","adj.","人造的；人工的","Artificial light can't replace a sunrise.","人造的灯光，代替不了日出。",""],[614,3,"athletic","/æθˈletik/",[["adj","运动的，健壮的"]],[],"","adj.","健壮的；运动的","You don't need to be athletic to enjoy a walk.","享受散步，不需要多好的运动天赋。",""],[615,3,"awkward","/ˈɔːkwəd/",[["adj","令人尴尬的，使人难堪的；紧张的，不舒适的；难办的，难用的，不好操作的，难应付的:笨拙的"]],[],"","adj.","尴尬的；笨拙的","Every first step is a little awkward.","每一个第一步，都有点笨拙。",""],[616,3,"damp","/dæmp/",[["adj","潮湿的"]],[],"","adj.","潮湿的","The damp earth smells sweet after rain.","雨后潮湿的泥土，闻起来甜甜的。",""],[617,3,"dash","/dæʃ/",[["v","猛冲，疾跑；猛掷，猛击"],["n","（添加物质的）少许，少量；猛冲，疾跑"]],[],"","n.","少许；v. 猛冲","Add a dash of humour to any hard day.","给难熬的日子，加一点幽默。",""],[618,3,"restrict","/riˈstrikt/",[["v","限制，约束"]],[],"","v.","限制；约束","Don't restrict your dreams to what others expect.","别把你的梦，限制在别人的期待里。",""],[619,3,"sacrifice","/ˈsækrifais/",[["v","牺牲（for）"],["n","祭品"]],[],"","n.","牺牲；v. 牺牲","Every achievement asks for a small sacrifice.","每一项成就，都需要一点小小的牺牲。",""],[620,3,"minimize","/ˈminimaiz/",[["v","使减（缩）小到最低；使显得不重要，轻视"]],[],"","v.","使减到最少","Minimize distractions, maximize focus.","把干扰降到最低，把专注提到最高。",""],[621,3,"miracle","/ˈmirəkl/",[["n","奇迹；神迹"]],[],"","n.","奇迹","Every sunrise is a quiet miracle.","每一次日出，都是一个安静的奇迹。",""],[622,3,"multiple","/ˈmʌltipl/",[["adj","多种的；数量多的"]],[],"","adj.","多种的；多个的","There are multiple paths up the mountain.","上山的路，不止一条。",""],[623,3,"neglect","/niˈglekt/",[["v","&"],["n","忽视，忽略"]],[],"","v.","忽视；n. 疏忽","Neglect a garden for a month and it becomes a forest.","一个月不打理，花园就成了森林。",""],[624,3,"notorious","/nəuˈtɔːriəs/",[["adj","臭名昭著的，声名狼藉的"]],[],"","adj.","臭名昭著的","My cat is notorious for stealing socks.","我的猫偷袜子是出了名的。",""],[625,3,"degrade","/diˈgreid/",[["v","降解；使情况恶化；贬低"]],[],"","v.","降解；贬低","Some plastic takes centuries to degrade.","有些塑料要几百年才能降解。",""],[626,3,"depart","/diˈpɑːt/",[["v","离开；出发，动身"]],[],"","v.","离开；出发","Li Bai was about to depart by boat when songs rose from the shore.","李白乘舟将欲行，忽闻岸上踏歌声。","李白"],[627,2,"accelerate","/ækˈseləreit/",[["v","加速"]],[],"","v.","加速","Trying to accelerate everything only slows you down.","欲速则不达。","孔子"],[628,2,"adore","/əˈdɔː/",[["v","爱慕，崇拜"]],[],"","v.","爱慕；非常喜欢","Children adore stories that begin with \"once upon a time\".","孩子们最喜欢以“从前”开头的故事。",""],[629,2,"perspective","/pəˈspektiv/",[["n","（思考问题的）角度，观点，想法；景观远景；透视（画）法；透视效果"]],[],"","n.","视角；观点","Change your perspective, and the problem changes too.","换个角度，问题也就变了。",""],[630,2,"category","/ˈkætigəri/",[["n","种类；分类"]],[],"","n.","种类；类别","Some books don't fit any category, and that's their charm.","有些书无法归类，这正是它们的魅力。",""],[631,2,"exclude","/iksˈkluːd/",[["v","排除；拒绝，阻止；排除…的可能性；对…不予考虑"]],[],"","v.","排除；拒绝","Don't exclude anyone from the circle.","别把任何人排除在圈子外。",""],[632,2,"pregnant","/ˈpregnənt/",[["adj","怀孕的"]],[],"","adj.","怀孕的","The pregnant cat chose our sofa as her nest.","那只怀孕的猫，选了我们的沙发当窝。",""],[633,2,"random","/ˈrændəm/",[["adj","随机的 （at ~ 随机地）"]],[],"","adj.","随机的","A random act of kindness can change someone's day.","一个随手的善举，可能改变某人的一天。",""],[634,2,"rebel","/ˈreblˌriˈbel/",[["v","造反"],["n","造反者"]],[],"","v.","反叛；n. 叛逆者","Teenagers rebel; that's how they find themselves.","青少年会叛逆，那是他们寻找自我的方式。",""],[635,2,"leak","/liːk/",[["v","渗出，泄露；泄露，透露（秘密信息）"]],[],"","v.","泄露；渗漏","Light leaks through the curtains at dawn.","黎明时分，光从窗帘缝里漏了进来。",""],[636,2,"starve","/stɑːv/",[["v","（使）挨饿，饿死"]],[],"","v.","挨饿；渴望","A mind that stops reading starts to starve.","停止阅读的头脑，会开始挨饿。",""],[637,2,"sting","/stɪŋ/",[["v","刺，蜇，叮；（使）感觉刺痛，感觉灼痛"],["v","（言谈）刺痛，刺伤，惹恼"],["n","刺伤；叮伤；蜇痛"]],[],"","v.","刺痛；n. 刺痛","Cold words sting more than cold wind.","冷言冷语，比冷风更刺痛人。",""],[638,2,"sustainable","/səˈsteɪnəbl/",[["adj","可持续的；（自然资源）可持续的，不破坏环境的"]],[],"","adj.","可持续的","Sustainable progress is slow and steady.","可持续的进步，缓慢而稳定。",""],[639,2,"temptation","/tempˈteɪʃn/",[["n","引诱，诱惑；诱惑物，诱因"]],[],"","n.","诱惑","I can resist everything except temptation.","除了诱惑，我什么都能抵挡。","王尔德"],[640,2,"tiresome","/ˈtaɪəsəm/",[["adj","令人厌倦的；讨厌的，烦人的"]],[],"","adj.","令人厌倦的","Practice can be tiresome, but mastery is sweet.","练习可能乏味，但精通的感觉很甜。",""],[641,2,"tourism","/ˈtʊərɪzəm/",[["n","旅游业"]],[],"","n.","旅游业","Tourism brought new life to the old fishing village.","旅游业给古老的渔村带来了新生机。",""],[642,2,"transition","/trænˈzɪʃn/",[["n","过渡，转变"],["v","（使）过渡，转变，变迁"]],[],"","n.","过渡；转变","Dawn is the transition from dream to day.","黎明，是从梦境到白昼的过渡。",""],[643,2,"allocate","/ˈæləkeit/",[["v","分配"]],[],"","v.","分配","Allocate your time like money: wisely.","像分配钱一样，明智地分配你的时间。",""],[644,2,"angle","/ˈæŋgl/",[["n","角度；观点，立场"],["v","（使）朝向；（使）转向"]],[],"","n.","角度；v. 转向","Seen from one angle, a ridge; from another, a peak.","横看成岭侧成峰。","苏轼"],[645,2,"aptitude","/ˈæptitjuːd/",[["n","天资；天生的才能；天赋"]],[],"","n.","天赋；才能","Interest often grows into aptitude.","兴趣，往往会长成天赋。",""],[646,2,"assertive","/əˈsəːtiv/",[["adj","观点明确的；坚决主张的"]],[],"","adj.","坚定自信的","Being assertive is being honest and kind at once.","坚定自信，就是既诚实又温和。",""],[647,2,"attribute","/ˈætribjuːt/",[["v","把…归因于；认为…是由于；属性，性质，特征"]],[],"","v.","把…归因于","She attributes her success to good habits.","她把自己的成功，归功于好习惯。",""],[648,2,"decisive","/diˈsaisiv/",[["adj","决定性的，关键的；坚决的，果断的"]],[],"","adj.","决定性的；果断的","The decisive moment came in the last minute.","决定性的时刻，在最后一分钟到来。",""],[649,2,"retain","/riˈtein/",[["v","保持，保留"]],[],"","v.","保持；保留","Retain your curiosity as you grow up.","长大的同时，保留你的好奇心。",""],[650,2,"retreat","/riˈtriːt/",[["n","减少，撤退；僻静处；隐居处"],["v","撤退"]],[],"","n.","僻静处；v. 撤退","My room is my little retreat from the noisy world.","我的房间，是我躲开喧嚣世界的小天地。",""],[651,2,"miserable","/ˈmizərəbl/",[["adj","悲惨的；苦恼的，痛苦的；（天气）阴郁的，令人苦恼的；（地方、形势）令人难受的，令人抑郁的"]],[],"","adj.","痛苦的；阴郁的","Even a miserable day has a sunset.","再糟糕的一天，也有日落。",""],[652,2,"illusion","/iˈluːʒən/",[["n","错觉；错误的观念"]],[],"","n.","错觉；幻想","Perfection is an illusion; progress is real.","完美是幻觉，进步是真实的。",""],[653,2,"numerous","/ˈnjuːmərəs/",[["adj","许多的，大量的"]],[],"","adj.","许多的；大量的","Numerous stars are hidden by city lights.","无数星星，被城市的灯光遮住了。",""],[654,2,"defect","/diˈfekt/",[["n","缺陷，缺点，毛病"]],[],"","n.","缺陷；缺点","A small defect makes handmade things unique.","小小的瑕疵，让手工制品独一无二。",""],[655,2,"deliberately","/diˈlibəritli/",[["adv","故意地；深思熟虑地；不慌不忙地；小心翼翼地；从容不迫地"]],[],"","adv.","深思熟虑地；故意地","I went to the woods because I wished to live deliberately.","我去林中，是因为我希望从容地生活。","梭罗"],[656,2,"democratic","/ˌdeməˈkrætik/",[["adj","民主的；民主制度的；民主主义的"]],[],"","adj.","民主的","A good class meeting is a democratic one.","好的班会，是民主的班会。",""],[657,2,"demolition","/ˌdeməˈliʃən/",[["n","（建筑物的）摧毁，拆毁，拆除；（体育运动等中的）大败，击溃"]],[],"","n.","拆除；摧毁","After the demolition, wildflowers covered the empty lot.","拆除之后，野花铺满了那块空地。",""],[658,2,"boundary","/ˈbaundəri/",[["n","边界，界限；分界线"]],[],"","n.","边界；界限","Life has a boundary; knowledge has none.","吾生也有涯，而知也无涯。","庄子"],[659,2,"slim","/slim/",[["adj","苗条的；纤细的；微薄的，不足的；少的，小的"],["v","变苗条"]],[],"","adj.","微小的；苗条的","The chances were slim, but she tried anyway.","机会渺茫，可她还是试了。",""],[660,1,"abnormal","/æbˈnɔːməl/",[["adj","不正常的；反常的"]],[],"","adj.","反常的","An abnormal heat wave hit the city in April.","四月，一场反常的热浪袭击了城市。",""],[661,1,"abundant","/əˈbʌndənt/",[["adj","丰富的，充裕的"]],[],"","adj.","丰富的；充裕的","Read abundantly, choose carefully; store up much, release a little.","博观而约取，厚积而薄发。","苏轼"],[662,1,"persist","/pəˈsist/",[["v","坚持，持续"]],[],"","v.","坚持；持续","Persist in carving, and even metal and stone can be engraved.","锲而不舍，金石可镂。","荀子"],[663,1,"cherish","/ˈtʃeriʃ/",[["v","珍爱，珍惜"]],[],"","v.","珍惜；珍爱","Keep cherishing old knowledge, and you will learn the new.","温故而知新。","孔子"],[664,1,"lately","/ˈleitli/",[["adv","最近，近来"]],[],"","adv.","最近；近来","Lately, I've been noticing the moon more.","最近，我常常注意到月亮。",""],[665,1,"exclaim","/iksˈkleim/",[["v","呼喊，惊叫"]],[],"","v.","呼喊；惊叫","\"Look, a shooting star!\" she exclaimed.","“快看，流星！”她惊呼道。",""],[666,1,"lighten","/ˈlaitn/",[["v","照亮；减轻；变亮"]],[],"","v.","减轻；照亮","A shared task lightens the load.","分担任务，就减轻了负担。",""],[667,1,"conscience","/ˈkɔnʃəns/",[["n","良心，良知；愧疚"]],[],"","n.","良心；良知","A clear conscience is a soft pillow.","问心无愧，就是一个柔软的枕头。","谚语"],[668,1,"time-consuming","/ˈtaimkənˌsjuːmiŋ/",[["adj","耗费时间的"]],[],"","adj.","耗时的","Good things are time-consuming, and worth it.","好东西都很费时间，也值得。",""],[669,1,"ambiguous","/æmˈbigjuəs/",[["adj","模棱两可的，含糊不清的"]],[],"","adj.","模棱两可的","Ambiguous answers lose marks; be clear.","模棱两可的答案会丢分，要写清楚。",""],[670,1,"applause","/əˈplɔːz/",[["n","鼓掌；赞扬"]],[],"","n.","掌声；称赞","Applause fades; what you learned stays.","掌声会消散，学到的东西会留下。",""],[671,1,"assemble","/əˈsembl/",[["v","聚集，集合；装配"]],[],"","v.","集合；装配","We assembled the bookshelf and argued only twice.","我们装好了书架，只吵了两次。",""],[672,1,"attain","/əˈtein/",[["v","获得，达到"]],[],"","v.","获得；达到","What one attains easily, one values little.","轻易得到的东西，人们往往不珍惜。",""],[673,1,"vacant","/ˈveikənt/",[["adj","空的；未被占用的"]],[],"","adj.","空的；未被占用的","A vacant seat on the bus felt like a small gift.","公交车上的一个空座，像一份小礼物。",""],[674,1,"deceive","/diˈsiːv/",[["v","欺骗，诈骗"]],[],"","v.","欺骗","We read the world wrong and say that it deceives us.","我们把世界看错了，反说它欺骗了我们。","泰戈尔"],[675,1,"bankrupt","/ˈbæŋkrʌpt/",[["adj","破产的"],["n","破产者"]],[],"","adj.","破产的","Laughter never goes bankrupt.","笑声永远不会破产。",""],[676,1,"restrain","/riˈstrein/",[["v","抑制，制止"]],[],"","v.","抑制；关住","A garden full of spring cannot be restrained; a red apricot branch reaches over the wall.","春色满园关不住，一枝红杏出墙来。","叶绍翁"],[677,1,"resume","/riˈzjuːm/",[["n","简历，履历"],["v","继续，重新开始"]],[],"","v.","继续；n. 简历","After the rain, the birds resumed their song.","雨停后，鸟儿又唱起了歌。",""],[678,1,"revenge","/riˈvendʒ/",[["n","&"],["v","复活，恢复生机"]],[],"","n.","报复；v. 报仇","The best revenge is to live well.","最好的报复，是好好生活。","英语谚语"],[679,1,"revive","/riˈvaiv/",[["v","复苏，恢复生机"]],[],"","v.","使复苏；恢复生机","A cup of hot tea can revive a frozen afternoon.","一杯热茶，能让冻僵的午后复苏。",""],[680,1,"modify","/ˈmɔdifai/",[["v","修饰；变更"]],[],"","v.","修改；修饰","Modify the plan, not the dream.","修改计划，而不是梦想。",""],[681,1,"obesity","/əuˈbiːsiti/",[["n","肥胖，肥胖症"]],[],"","n.","肥胖","Doctors warn that obesity is rising among children.","医生警告，儿童肥胖率正在上升。",""],[682,1,"delete","/diˈliːt/",[["v","删除，去除"]],[],"","v.","删除","Delete the negative comment, keep the lesson.","删掉负面的评论，留下教训。",""],[683,1,"volatile","/ˈvɔlətail/",[["adj","不稳定的，易变的；挥发性的"]],[],"","adj.","易变的；不稳定的","Spring weather is volatile: sun, rain, then sun again.","春天的天气多变：晴，雨，又晴。",""],[684,1,"bound","/baund/",[["adj","必定的；受（法律、义务或情况）约束（必须做某事）；有义务（做某事）；上限，极限；界限，限制（一般只用复数）"],["n","跳跃"],["v","跳跃着跑；形成…的边界（或界限）"]],[],"","adj.","必定的；受约束的","If you keep walking, you are bound to arrive.","只要一直走，就一定会到达。",""],[685,1,"worthwhile","/ˈwəːθˈwail/",[["adj","值得（做）的"]],[],"","adj.","值得的","Learning a language is worthwhile, one word at a time.","学一门语言是值得的，一次一个词。",""],[686,1,"overwhelm","/ˌəuvəˈwelm/",[["v","压倒；淹没；使不知所措；（感情或感觉）充溢，难以承受"]],[],"","v.","压倒；使不知所措","Don't let a long list overwhelm you; do one thing.","别被长长的清单压垮，先做一件事。",""],[687,1,"simulate","/ˈsimjuleit/",[["v","假装；模仿，仿真"]],[],"","v.","模拟；假装","The planetarium simulates a sky full of stars.","天文馆模拟出一片满是星星的夜空。",""],[688,1,"simultaneously","/saiməlˈteiniəsli/",[["adv","同时地，同时发生地"]],[],"","adv.","同时地","The moon rises over the sea; far apart, we see it simultaneously.","海上生明月，天涯共此时。","张九龄"]];
